// docs/proposed-new-cards.js
//
// PROPOSED NEW CARDS - NOT SHIPPED. A HUMAN MUST REVIEW EVERY CARD (medical accuracy,
// wording, difficulty, exam tags) BEFORE ANY OF THEM MOVE INTO js/cards/*.js.
//
// - This file is deliberately outside js/cards and is not imported by the app or tests.
// - 117 cards drafted to fill coverage gaps found in docs/CONTENT-AUDIT.md
//   (dermatology, ophthalmology/ENT, urology, ethics, orthopedic tumors, biostatistics,
//   geriatrics/prevention, nutrition, nerve injuries).
// - Ids use the "nw" prefix (nwd dermatology, nwo ophtho/ENT, nwu urology, nwe ethics,
//   nwm MSK, nwb biostat, nwg geriatrics, nwn nutrition, nwa anatomy); none collide with live ids.
// - "source_ref" is an extra, non-schema field holding a public reference URL. Strip it
//   (or keep it, if the schema is extended) when promoting a card. Some publisher sites block
//   automated checks, so confirm each link by hand.
// - Dermatology/ophthalmology/ENT have no canonical subject in js/cardschema.js, so they sit in
//   "Multisystem / Mixed" with a specialty tag; urology and orthopedics use "Surgery".
// - All cards were self-checked with validateCard(), the clue-length rules and strictLeakReport()
//   (tools/validate-new-cards check is reproducible: see docs/CONTENT-AUDIT.md).

export const PROPOSED_NEW_CARDS = [
{"id":"nwd01","subj":"Multisystem / Mixed","bw":["Salmon-pink scaly lesions on elbows and knees","Pinpoint bleeding when scale is scraped (Auspitz sign)","Nail pitting and onycholysis","New lesions along a scratch line"],"ans":"Plaque Psoriasis","d":["Seborrheic Dermatitis","Lichen Planus"],"tp":"Th17/IL-23-driven keratinocyte hyperproliferation. Mild: topical steroids and vitamin D analogs. Moderate-severe: phototherapy or biologics (TNF, IL-17, IL-23 inhibitors).","ww":{"Seborrheic Dermatitis":"Greasy scale in scalp and nasolabial folds, no Auspitz sign.","Lichen Planus":"Violaceous flat-topped papules with Wickham striae."},"exams":["step1","step2","comlex1","comlex2","shelf_im"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","psoriasis"],"hx":true,"yr":2,"pearls":["Parakeratosis and Munro microabscesses on biopsy","Guttate form follows streptococcal pharyngitis","Associated with psoriatic arthritis and metabolic syndrome"],"source_ref":"https://medlineplus.gov/psoriasis.html"},
{"id":"nwd02","subj":"Multisystem / Mixed","bw":["Flaccid blisters that rupture easily","Painful oral erosions often appear first","Nikolsky sign positive","Intraepidermal acantholysis on biopsy"],"ans":"Pemphigus Vulgaris","d":["Bullous Pemphigoid","Dermatitis Herpetiformis"],"tp":"IgG against desmoglein 3 (and 1) causes suprabasal acantholysis. Direct immunofluorescence shows a fishnet intercellular pattern. Treat with systemic corticosteroids and rituximab.","ww":{"Bullous Pemphigoid":"Tense subepidermal bullae in the elderly, negative Nikolsky, linear IgG at the basement membrane.","Dermatitis Herpetiformis":"Grouped pruritic vesicles on extensor surfaces with celiac disease."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"immunology","tags":["dermatology","bullous","autoimmune"],"hx":true,"yr":2,"pearls":["Desmosome (desmoglein) attack gives a \"row of tombstones\" appearance","Mucosal involvement is common, unlike pemphigoid","Associated with HLA-DR4 and thymoma/myasthenia in paraneoplastic forms"],"source_ref":"https://dermnetnz.org/topics/pemphigus-vulgaris"},
{"id":"nwd03","subj":"Multisystem / Mixed","bw":["Elderly patient with tense blisters on flexural skin","Preceding itchy urticarial plaques","Nikolsky sign negative","Linear IgG and C3 along the basement membrane"],"ans":"Bullous Pemphigoid","d":["Pemphigus Vulgaris","Erythema Multiforme"],"tp":"IgG against hemidesmosomal BP180/BP230 causes a subepidermal split with eosinophils. Treat with topical clobetasol or systemic steroids; DPP-4 inhibitors and some drugs can trigger it.","ww":{"Pemphigus Vulgaris":"Flaccid intraepidermal blisters with oral erosions and fishnet immunofluorescence.","Erythema Multiforme":"Target lesions after HSV or drugs, no linear basement membrane IgG."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"immunology","tags":["dermatology","bullous","autoimmune"],"hx":true,"yr":2,"pearls":["Type II hypersensitivity against hemidesmosomes","Oral involvement is uncommon (unlike pemphigus)","Anti-BP180 titer tracks disease activity"],"source_ref":"https://dermnetnz.org/topics/bullous-pemphigoid"},
{"id":"nwd04","subj":"Multisystem / Mixed","bw":["Intensely itchy grouped vesicles on elbows, knees and buttocks","Gluten sensitivity with chronic diarrhea","Granular IgA deposits in dermal papillary tips","Dramatic response to dapsone"],"ans":"Dermatitis Herpetiformis","d":["Pemphigus Vulgaris","Scabies"],"tp":"Cutaneous manifestation of celiac disease (HLA-DQ2/DQ8) with IgA-tTG deposition. Treat with a strict gluten-free diet; dapsone controls the rash (check G6PD).","ww":{"Pemphigus Vulgaris":"Flaccid blisters with mucosal erosions and intercellular IgG.","Scabies":"Burrows in finger webs with nocturnal itching and contacts affected."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","celiac","vesiculobullous"],"hx":true,"yr":2,"pearls":["Dapsone can cause hemolysis and methemoglobinemia","Skin lesions may persist when GI symptoms are absent","Associated with lymphoma risk in untreated celiac disease"],"source_ref":"https://dermnetnz.org/topics/dermatitis-herpetiformis"},
{"id":"nwd05","subj":"Multisystem / Mixed","bw":["Painful targetoid rash 1-3 weeks after starting a new drug","Hemorrhagic erosions of lips and conjunctiva","Sheet-like epidermal sloughing","Positive Nikolsky sign"],"ans":"Stevens-Johnson Syndrome / TEN","d":["Staphylococcal Scalded Skin Syndrome","Erythema Multiforme"],"tp":"Severe T-cell-mediated drug reaction (allopurinol, sulfonamides, lamotrigine, carbamazepine, nevirapine). Stop the drug and give burn-unit supportive care; <10% BSA is SJS, >30% is TEN.","ww":{"Staphylococcal Scalded Skin Syndrome":"Superficial peeling in an infant without mucosal involvement (toxin cleaves desmoglein-1).","Erythema Multiforme":"Target lesions on the extremities with minimal mucosal disease, usually after HSV."},"exams":["step1","step2","step3","comlex1","comlex2","shelf_im"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","drug-reaction","emergency"],"hx":true,"yr":2,"pearls":["HLA-B*1502 (carbamazepine, Asian ancestry) and HLA-B*5801 (allopurinol) are risk alleles","Cyclosporine or IVIG are used in selected patients; steroids are controversial","Ophthalmology consult prevents ocular scarring"],"source_ref":"https://dermnetnz.org/topics/drug-hypersensitivity-syndrome"},
{"id":"nwd06","subj":"Multisystem / Mixed","bw":["Rash, fever and facial swelling 2-8 weeks after a new anticonvulsant or allopurinol","Peripheral eosinophilia","Hepatitis with lymphadenopathy","HHV-6 reactivation"],"ans":"DRESS Syndrome","d":["Stevens-Johnson Syndrome / TEN","Serum Sickness"],"tp":"Delayed drug hypersensitivity with visceral involvement (liver most common). Stop the offending drug and give systemic corticosteroids with a slow taper because relapses are common.","ww":{"Stevens-Johnson Syndrome / TEN":"Mucosal erosions and epidermal detachment within 1-3 weeks.","Serum Sickness":"Fever, arthralgia and urticaria 1-2 weeks after a heterologous antiserum or beta-lactam, no eosinophilic organ injury."},"exams":["step2","step3","comlex2","shelf_im"],"baseDifficulty":3,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","drug-reaction"],"hx":true,"yr":2,"pearls":["Latency is longer (2-8 weeks) than most drug rashes","Common culprits: carbamazepine, phenytoin, allopurinol, vancomycin, sulfonamides","Check LFTs, creatinine and eosinophils in any severe drug rash"],"source_ref":"https://dermnetnz.org/topics/drug-hypersensitivity-syndrome"},
{"id":"nwd07","subj":"Multisystem / Mixed","bw":["Comedones, papules and pustules on the face and upper back in a teenager","Pilosebaceous plugging with Cutibacterium overgrowth","Scarring in severe nodulocystic disease","Worsening with androgens"],"ans":"Acne Vulgaris","d":["Rosacea","Folliculitis"],"tp":"Mild disease: topical retinoid plus benzoyl peroxide. Moderate: add topical or oral antibiotic (doxycycline). Severe or scarring: isotretinoin (teratogenic, iPLEDGE; monitor lipids and LFTs). Women: OCPs or spironolactone.","ww":{"Rosacea":"Middle-aged flushing with telangiectasias and papulopustules without comedones.","Folliculitis":"Follicular pustules after hot tub exposure (Pseudomonas) or shaving."},"exams":["step1","step2","comlex1","comlex2","shelf_fm"],"baseDifficulty":1,"questionType":"management","source":"clinical_medicine","tags":["dermatology","acne","isotretinoin"],"hx":true,"yr":2,"pearls":["Isotretinoin: cheilitis, hypertriglyceridemia, depression concern, birth defects","Do not combine tetracyclines with isotretinoin (pseudotumor cerebri)","Monotherapy with antibiotics promotes resistance"],"source_ref":"https://medlineplus.gov/acne.html"},
{"id":"nwd08","subj":"Multisystem / Mixed","bw":["Central facial flushing triggered by alcohol or hot drinks","Telangiectasias and papulopustules without comedones","Bulbous nasal enlargement in advanced disease","Ocular irritation in some patients"],"ans":"Rosacea","d":["Acne Vulgaris","Seborrheic Dermatitis"],"tp":"Chronic inflammatory facial dermatosis of adults. Avoid triggers and use sunscreen. Topical metronidazole, azelaic acid or ivermectin; oral doxycycline for moderate-severe disease.","ww":{"Acne Vulgaris":"Comedones present, typically adolescents.","Seborrheic Dermatitis":"Greasy scale in nasolabial folds and eyebrows."},"exams":["step2","comlex2","shelf_fm"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","rosacea"],"hx":true,"yr":2,"pearls":["Rhinophyma is sebaceous hyperplasia of the nose","Ocular rosacea can cause blepharitis and keratitis","No comedones - key distinction from acne"],"source_ref":"https://medlineplus.gov/rosacea.html"},
{"id":"nwd09","subj":"Multisystem / Mixed","bw":["Annular itchy lesion with raised scaly edge","Central clearing","Hyphae on potassium hydroxide prep","Wrestler with a new skin patch"],"ans":"Tinea Corporis","d":["Nummular Eczema","Granuloma Annulare"],"tp":"Superficial dermatophyte infection (Trichophyton, Microsporum). Treat with topical terbinafine or azoles; oral therapy for extensive disease. Never treat with topical steroids alone.","ww":{"Nummular Eczema":"Coin-shaped vesicular eczema with no hyphae and no central clearing.","Granuloma Annulare":"Smooth non-scaly ring of papules, often over the hands of diabetics."},"exams":["step1","step2","comlex1","comlex2","shelf_fm"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"microbiology","tags":["dermatology","dermatophyte","fungal"],"hx":true,"yr":2,"pearls":["KOH shows septate branching hyphae","Steroid creams cause tinea incognito","Tinea capitis requires oral therapy"],"source_ref":"https://dermnetnz.org/topics/tinea-corporis"},
{"id":"nwd10","subj":"Multisystem / Mixed","bw":["Hypopigmented or tan macules on the upper trunk in a humid climate","Fine scale appearing on scraping","Spaghetti-and-meatballs pattern on KOH","Yellow-green fluorescence under Wood lamp"],"ans":"Pityriasis Versicolor","d":["Vitiligo","Tinea Corporis"],"tp":"Caused by Malassezia yeast. Treat with topical selenium sulfide or ketoconazole; oral fluconazole for extensive disease. Pigment changes may take months to normalize.","ww":{"Vitiligo":"Totally depigmented patches with chalk-white color and no scale.","Tinea Corporis":"Annular scaling lesions with central clearing and hyphae without yeast forms."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"microbiology","tags":["dermatology","fungal","malassezia"],"hx":true,"yr":2,"pearls":["Lipophilic yeast; recurs in warm weather","Not contagious","Hypopigmentation results from azelaic acid production inhibiting melanocytes"],"source_ref":"https://dermnetnz.org/topics/pityriasis-versicolor"},
{"id":"nwd11","subj":"Multisystem / Mixed","bw":["Thickened yellow brittle toenail","Subungual hyperkeratotic debris","Diabetic patient with chronic athlete foot","Positive PAS stain of nail clippings"],"ans":"Onychomycosis","d":["Nail Psoriasis","Paronychia"],"tp":"Usually Trichophyton rubrum. Confirm with KOH, PAS or culture before treating. Oral terbinafine for 12 weeks (monitor LFTs) is most effective; topical agents have low cure rates.","ww":{"Nail Psoriasis":"Pitting and oil-drop spots with psoriatic plaques elsewhere.","Paronychia":"Painful swelling of the nail fold after manicure with Candida or S. aureus."},"exams":["step2","comlex2","shelf_fm"],"baseDifficulty":2,"questionType":"dx_to_tx","source":"pharmacology","tags":["dermatology","fungal","terbinafine"],"hx":true,"yr":2,"pearls":["Terbinafine inhibits squalene epoxidase","Itraconazole is an alternative but has many CYP interactions","Confirm diagnosis because many dystrophic nails are not fungal"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/?term=onychomycosis+statpearls"},
{"id":"nwd12","subj":"Multisystem / Mixed","bw":["Intense itching worse at night","Burrows in finger webs and wrists","Itchy papules in several household members","Mites, eggs or feces on skin scraping"],"ans":"Scabies","d":["Atopic Dermatitis","Head Lice"],"tp":"Sarcoptes scabiei mite. Treat with permethrin 5% cream to the whole body (or oral ivermectin), treat close contacts simultaneously and wash linens. Crusted (Norwegian) scabies occurs in the immunocompromised.","ww":{"Atopic Dermatitis":"Flexural itching with a personal or family atopy history and no burrows.","Head Lice":"Scalp itching with nits attached to hair shafts."},"exams":["step1","step2","comlex1","comlex2","shelf_peds"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"microbiology","tags":["dermatology","parasitic","scabies"],"hx":true,"yr":2,"pearls":["Itching persists for weeks after successful treatment","Ivermectin is not approved in young children or pregnancy","Common in nursing homes and institutional outbreaks"],"source_ref":"https://medlineplus.gov/scabies.html"},
{"id":"nwd13","subj":"Multisystem / Mixed","bw":["Scalp itching in a schoolchild","Nits glued to hair shafts near the scalp","Behind-the-ear excoriations","Spread by close contact at school"],"ans":"Head Lice Infestation","d":["Scabies","Seborrheic Dermatitis"],"tp":"Pediculus humanus capitis. Treat with permethrin 1% or other topical pediculicides (or oral ivermectin) and repeat in 7-10 days. Children need not be excluded from school.","ww":{"Scabies":"Burrows in webs of fingers and nocturnal generalized itching.","Seborrheic Dermatitis":"Greasy scale without live organisms."},"exams":["step2","comlex2","shelf_peds"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"microbiology","tags":["dermatology","parasitic","pediatrics"],"hx":true,"yr":2,"pearls":["Live lice are rarely seen; nits are the clue","Resistance to permethrin is common","Not a sign of poor hygiene"],"source_ref":"https://dermnetnz.org/topics/head-lice"},
{"id":"nwd14","subj":"Multisystem / Mixed","bw":["Flesh-colored dome-shaped papules with central dimple in a child","Spread among swimmers and by autoinoculation","Large numerous lesions in advanced HIV","Henderson-Paterson bodies"],"ans":"Molluscum Contagiosum","d":["Verruca Vulgaris","Varicella"],"tp":"Poxvirus infection that usually resolves spontaneously over months. Treatment options include curettage, cryotherapy or cantharidin. Widespread or giant lesions suggest immunodeficiency.","ww":{"Verruca Vulgaris":"Rough papules with black dots from thrombosed capillaries (HPV).","Varicella":"Crops of vesicles in different stages with fever."},"exams":["step1","step2","comlex1","comlex2","shelf_peds"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"microbiology","tags":["dermatology","poxvirus","pediatrics"],"hx":true,"yr":2,"pearls":["Cytoplasmic inclusions (Henderson-Paterson bodies)","Genital lesions in adults are sexually transmitted","In HIV, lesions can be large and facial"],"source_ref":"https://dermnetnz.org/topics/molluscum-contagiosum"},
{"id":"nwd15","subj":"Multisystem / Mixed","bw":["Rough hyperkeratotic papules on the hands","Pinpoint black dots from thrombosed capillaries","Plantar lesions that hurt with walking","Koebner phenomenon"],"ans":"Verruca Vulgaris","d":["Molluscum Contagiosum","Seborrheic Keratosis"],"tp":"Cutaneous HPV (types 1, 2, 4) infection. Treat with salicylic acid, cryotherapy or watchful waiting since many resolve spontaneously.","ww":{"Molluscum Contagiosum":"Umbilicated smooth papules in children.","Seborrheic Keratosis":"Waxy stuck-on brown plaque in the elderly with horn cysts."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"microbiology","tags":["dermatology","HPV","warts"],"hx":true,"yr":2,"pearls":["Genital warts are HPV 6 and 11","Self-inoculation spreads lesions","Persistent periungual warts may need dermatology referral"],"source_ref":"https://medlineplus.gov/warts.html"},
{"id":"nwd16","subj":"Multisystem / Mixed","bw":["Sharply demarcated milk-white macules on hands and periorbital skin","Enhanced by Wood lamp","Associated autoimmune thyroiditis","Absent melanocytes on biopsy"],"ans":"Vitiligo","d":["Pityriasis Versicolor","Albinism"],"tp":"Autoimmune destruction of melanocytes. Screen for thyroid disease, type 1 diabetes and adrenal insufficiency. Treat with topical steroids or calcineurin inhibitors, phototherapy or topical JAK inhibitor.","ww":{"Pityriasis Versicolor":"Scaly hypopigmented macules that fluoresce yellow-green.","Albinism":"Generalized lack of pigment since birth with normal melanocyte number."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","autoimmune","pigment"],"hx":true,"yr":2,"pearls":["Koebner phenomenon can occur at trauma sites","Associated with halo nevi and alopecia areata","Sunscreen protects depigmented skin"],"source_ref":"https://medlineplus.gov/vitiligo.html"},
{"id":"nwd17","subj":"Multisystem / Mixed","bw":["Sudden round patches of smooth hair loss","Exclamation-point hairs at the edge","Nail pitting","Personal history of thyroiditis"],"ans":"Alopecia Areata","d":["Telogen Effluvium","Tinea Capitis"],"tp":"T-cell-mediated attack on anagen follicles with nonscarring hair loss. Treat with intralesional corticosteroids; JAK inhibitors (baricitinib) are approved for severe disease. Regrowth may be spontaneous.","ww":{"Telogen Effluvium":"Diffuse shedding 2-3 months after surgery, childbirth or illness.","Tinea Capitis":"Scaly patch with broken hairs and black dots in a child."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"immunology","tags":["dermatology","autoimmune","hair"],"hx":true,"yr":2,"pearls":["Follicles appear \"bees in a swarm\" on biopsy","Associated with atopy, vitiligo, thyroid disease","Totalis and universalis are extensive variants"],"source_ref":"https://medlineplus.gov/hairloss.html"},
{"id":"nwd18","subj":"Multisystem / Mixed","bw":["Waxy brown \"stuck-on\" plaque in an elderly patient","Keratin-filled horn cysts","Benign and requires no treatment","Sudden eruption of many lesions suggests internal cancer"],"ans":"Seborrheic Keratosis","d":["Actinic Keratosis","Melanoma"],"tp":"Common benign epidermal tumor. Treat only for symptoms or cosmesis (cryotherapy, curettage). The Leser-Trelat sign (abrupt crop of lesions) may accompany GI adenocarcinoma.","ww":{"Actinic Keratosis":"Rough erythematous scaly papule on sun-exposed skin that may become squamous cell carcinoma.","Melanoma":"Asymmetric pigmented lesion with irregular borders and recent growth."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","benign-neoplasm"],"hx":true,"yr":2,"pearls":["Sharply demarcated with a \"pasted on\" appearance","Not premalignant","Biopsy any lesion with atypical features to exclude melanoma"],"source_ref":"https://dermnetnz.org/topics/seborrhoeic-keratosis"},
{"id":"nwd19","subj":"Multisystem / Mixed","bw":["Rough sandpaper-like scaly spots on the scalp and hands of a fair-skinned older farmer","Chronic sun exposure","Precursor of a cutaneous squamous cancer","Treated with liquid nitrogen"],"ans":"Actinic Keratosis","d":["Seborrheic Keratosis","Basal Cell Carcinoma"],"tp":"UV-induced dysplasia of keratinocytes. Treat with cryotherapy, topical 5-fluorouracil or imiquimod; a lesion that thickens or ulcerates needs biopsy for SCC.","ww":{"Seborrheic Keratosis":"Waxy stuck-on plaque with horn cysts and no malignant potential.","Basal Cell Carcinoma":"Pearly papule with telangiectasia and rolled borders."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","premalignant","UV"],"hx":true,"yr":2,"pearls":["Risk of progression to SCC is about 1% per lesion-year","Immunosuppressed transplant patients are at highest risk","Daily sunscreen reduces new lesions"],"source_ref":"https://dermnetnz.org/topics/actinic-keratosis"},
{"id":"nwd20","subj":"Multisystem / Mixed","bw":["Single oval scaly \"herald\" patch followed by smaller lesions in a Christmas-tree pattern","Young adult with preceding upper respiratory illness","Lesions follow skin cleavage lines on the trunk","Resolves in 6-8 weeks"],"ans":"Pityriasis Rosea","d":["Secondary Syphilis","Guttate Psoriasis"],"tp":"Self-limited exanthem possibly related to HHV-6/7 reactivation. Reassure; antihistamines or topical steroids for itch. Check RPR if palms/soles are involved or sexual risk exists.","ww":{"Secondary Syphilis":"Rash including palms and soles with condylomata lata and positive RPR.","Guttate Psoriasis":"Teardrop papules after streptococcal pharyngitis without a herald patch."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","exanthem"],"hx":true,"yr":2,"pearls":["Collarette of scale trailing at the edge","Spares palms and soles (unlike secondary syphilis)","No specific therapy needed"],"source_ref":"https://dermnetnz.org/topics/pityriasis-rosea"},
{"id":"nwd21","subj":"Multisystem / Mixed","bw":["Pruritic purple polygonal flat-topped papules on the wrists","White lacy lines on the buccal mucosa","Associated hepatitis C infection","Sawtooth lymphocytic band at the dermoepidermal junction"],"ans":"Lichen Planus","d":["Plaque Psoriasis","Lichen Sclerosus"],"tp":"T-cell-mediated lichenoid dermatitis. Wickham striae are the hallmark. Treat with high-potency topical steroids; test for hepatitis C. Erosive oral lesions carry a small SCC risk.","ww":{"Plaque Psoriasis":"Silvery scaling plaques on extensor surfaces with Auspitz sign.","Lichen Sclerosus":"White atrophic vulvar plaque with parchment texture and SCC risk."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","lichenoid","hepatitis-c"],"hx":true,"yr":2,"pearls":["Six Ps: pruritic, purple, polygonal, planar, papules, plaques","Koebner phenomenon is present","Oral variant may be erosive and painful"],"source_ref":"https://dermnetnz.org/topics/lichen-planus"},
{"id":"nwd22","subj":"Multisystem / Mixed","bw":["Recurrent painful nodules and abscesses in the axillae and groin","Double-ended comedones","Sinus tracts and rope-like scars","Obesity and smoking"],"ans":"Hidradenitis Suppurativa","d":["Cutaneous Abscess","Pilonidal Disease"],"tp":"Chronic follicular occlusion disease of apocrine-bearing skin. Treat with weight loss, smoking cessation, topical clindamycin and oral doxycycline; adalimumab or secukinumab for moderate-severe disease; surgery for fixed tracts.","ww":{"Cutaneous Abscess":"Single acute fluctuant S. aureus lesion drained once, not recurrent in several folds.","Pilonidal Disease":"Hair-containing sinus in the natal cleft of a young man."},"exams":["step2","comlex2","shelf_surg"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","follicular-occlusion"],"hx":true,"yr":2,"pearls":["Associated with Crohn disease and metabolic syndrome","Not a primary bacterial infection","Hurley stages guide treatment"],"source_ref":"https://dermnetnz.org/topics/hidradenitis-suppurativa"},
{"id":"nwd23","subj":"Multisystem / Mixed","bw":["Rapidly enlarging painful ulcer with a violaceous undermined border","Ulcer worsened by minor trauma","Ulcerative colitis flare","Negative cultures"],"ans":"Pyoderma Gangrenosum","d":["Necrotizing Fasciitis","Venous Stasis Ulcer"],"tp":"Neutrophilic dermatosis associated with IBD, rheumatoid arthritis and hematologic malignancy. Diagnosis of exclusion; treat with systemic corticosteroids or cyclosporine and avoid surgical debridement (pathergy).","ww":{"Necrotizing Fasciitis":"Pain out of proportion with gas and rapid spread requiring emergent surgery.","Venous Stasis Ulcer":"Shallow irregular ulcer at the medial malleolus with edema and hyperpigmentation."},"exams":["step2","comlex2","shelf_im"],"baseDifficulty":3,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","neutrophilic","IBD"],"hx":true,"yr":2,"pearls":["Pathergy: new lesions at sites of trauma","Surgical debridement worsens it","Look for underlying IBD or myeloproliferative disease"],"source_ref":"https://dermnetnz.org/topics/pyoderma-gangrenosum"},
{"id":"nwd24","subj":"Multisystem / Mixed","bw":["Linear vesicles on the forearm after hiking","Itchy rash under a belt buckle or earlobe","Positive patch test","Delayed reaction 24-72 hours after exposure"],"ans":"Allergic Contact Dermatitis","d":["Irritant Contact Dermatitis","Atopic Dermatitis"],"tp":"Type IV (delayed) hypersensitivity to haptens such as urushiol (poison ivy), nickel or fragrance. Identify and avoid the allergen; treat with topical or short oral corticosteroid courses; patch testing confirms the trigger.","ww":{"Irritant Contact Dermatitis":"Burning dry rash on hands of a nurse from soap exposure without prior sensitization.","Atopic Dermatitis":"Flexural eczema in an atopic child with asthma."},"exams":["step1","step2","comlex1","comlex2","shelf_fm"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"immunology","tags":["dermatology","hypersensitivity","type-IV"],"hx":true,"yr":2,"pearls":["Poison ivy oil can persist on clothes and pets","Nickel is the most common contact allergen","Irritant dermatitis needs no prior sensitization"],"source_ref":"https://dermnetnz.org/topics/allergic-contact-dermatitis"},
{"id":"nwd25","subj":"Multisystem / Mixed","bw":["Spreading warm erythematous tender skin with ill-defined borders","Fever after a minor leg wound","Lymphangitic streaking","Streptococcus pyogenes or Staph aureus"],"ans":"Cellulitis","d":["Erysipelas","Venous Stasis Dermatitis"],"tp":"Infection of dermis and subcutaneous fat. Non-purulent: cephalexin or dicloxacillin (add MRSA coverage with TMP-SMX or doxycycline if purulent or risk factors). Elevate the limb; hospitalize if systemic toxicity.","ww":{"Erysipelas":"Sharply demarcated raised superficial lesion of the face or lower leg.","Venous Stasis Dermatitis":"Bilateral brownish pigmented scaly legs without fever."},"exams":["step1","step2","step3","comlex1","comlex2","shelf_im","shelf_fm"],"baseDifficulty":1,"questionType":"dx_to_tx","source":"clinical_medicine","tags":["dermatology","cellulitis","skin-infection"],"hx":true,"yr":2,"pearls":["Bilateral \"cellulitis\" is usually stasis dermatitis","Draw a line around erythema to monitor","Consider necrotizing infection if pain is out of proportion"],"source_ref":"https://medlineplus.gov/cellulitis.html"},
{"id":"nwd26","subj":"Multisystem / Mixed","bw":["Intensely itchy serpiginous track on the foot after a beach vacation","Advancing 1-2 cm per day","Walking barefoot on sand contaminated by dog feces","Self-limited without therapy"],"ans":"Cutaneous Larva Migrans","d":["Scabies","Tinea Pedis"],"tp":"Hookworm larvae (Ancylostoma braziliense) penetrate skin but cannot invade deeper. Treat with ivermectin or albendazole.","ww":{"Scabies":"Burrows in finger webs with nocturnal itching and household spread.","Tinea Pedis":"Scaling and maceration between toes with hyphae on KOH."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"microbiology","tags":["dermatology","parasitic","travel"],"hx":true,"yr":2,"pearls":["Humans are a dead-end host","Differs from Strongyloides larva currens (fast-moving, perianal)","Topical thiabendazole is an alternative"],"source_ref":"https://dermnetnz.org/topics/cutaneous-larva-migrans"},
{"id":"nwd27","subj":"Multisystem / Mixed","bw":["Severe sunburn after minimal sun exposure in infancy","Freckling and early skin cancers","Neurologic deterioration in some subtypes","Defective excision of thymine dimers"],"ans":"Xeroderma Pigmentosum","d":["Albinism","Ataxia-Telangiectasia"],"tp":"Autosomal recessive nucleotide excision repair defect. UV-induced pyrimidine dimers accumulate, causing early BCC, SCC and melanoma. Strict sun protection is the cornerstone of management.","ww":{"Albinism":"Hypopigmentation from tyrosinase deficiency with normal DNA repair.","Ataxia-Telangiectasia":"Ataxia, telangiectasias and recurrent sinopulmonary infections with a double-strand break repair defect."},"exams":["step1","comlex1"],"baseDifficulty":2,"questionType":"mechanism","source":"genetics","tags":["dermatology","DNA-repair","genetics"],"hx":true,"yr":2,"pearls":["Nucleotide excision repair removes bulky UV lesions","Mismatch repair defects cause Lynch syndrome instead","Lifelong dermatologic surveillance is required"],"source_ref":"https://dermnetnz.org/topics/xeroderma-pigmentosum"},
{"id":"nwd28","subj":"Multisystem / Mixed","bw":["Bedbound patient with nonblanchable erythema over the sacrum","Full-thickness skin loss exposing subcutaneous fat","Exposed bone or muscle with eschar","Risk rises with moisture, immobility and malnutrition"],"ans":"Pressure Injury Staging","d":["Venous Stasis Ulcer","Arterial Insufficiency Ulcer"],"tp":"Stage 1: intact nonblanchable erythema. Stage 2: partial thickness with dermis exposed. Stage 3: full-thickness fat. Stage 4: muscle or bone. Prevent with repositioning every 2 hours, pressure-redistributing surfaces and nutrition.","ww":{"Venous Stasis Ulcer":"Shallow ulcer at the medial malleolus with leg edema.","Arterial Insufficiency Ulcer":"Punched-out painful ulcer on toes or lateral foot with absent pulses."},"exams":["step2","step3","comlex2","shelf_im","shelf_surg"],"baseDifficulty":2,"questionType":"management","source":"clinical_medicine","tags":["dermatology","geriatrics","pressure-injury"],"hx":true,"yr":2,"pearls":["Debride necrotic tissue in stage 3-4 lesions","Albumin alone is a poor nutrition marker","Common over sacrum, heels, ischial tuberosities, greater trochanter"],"source_ref":"https://medlineplus.gov/pressuresores.html"},
{"id":"nwd29","subj":"Multisystem / Mixed","bw":["Dry fish-scale skin on the shins sparing flexures","Onset in early childhood","Associated eczema and asthma","Absent granular layer on biopsy"],"ans":"Ichthyosis Vulgaris","d":["Atopic Dermatitis","Psoriasis Vulgaris"],"tp":"Autosomal semidominant filaggrin loss-of-function mutation causes retention hyperkeratosis. Treat with emollients and keratolytics (urea, lactic acid).","ww":{"Atopic Dermatitis":"Itchy flexural eczema with a normal granular layer.","Psoriasis Vulgaris":"Well-demarcated scaly plaques over extensor surfaces with nail pitting."},"exams":["step1","comlex1"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"genetics","tags":["dermatology","filaggrin","genetics"],"hx":true,"yr":2,"pearls":["Filaggrin mutations also predispose to atopic dermatitis","X-linked ichthyosis (steroid sulfatase deficiency) involves the flexures","Worse in winter"],"source_ref":"https://dermnetnz.org/topics/ichthyosis-vulgaris"},
{"id":"nwd30","subj":"Multisystem / Mixed","bw":["Greasy yellow scale in the scalp and eyebrows","Erythema in the nasolabial folds","Worsens with Parkinson disease or HIV","Cradle cap in infants"],"ans":"Seborrheic Dermatitis","d":["Plaque Psoriasis","Atopic Dermatitis"],"tp":"Inflammatory reaction to Malassezia on sebum-rich skin. Treat with ketoconazole or selenium shampoo and topical antifungal or low-potency steroid creams.","ww":{"Plaque Psoriasis":"Silvery plaques on extensor surfaces with Auspitz sign.","Atopic Dermatitis":"Pruritic flexural rash in an atopic patient with dry skin."},"exams":["step1","step2","comlex1","comlex2","shelf_peds"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","malassezia"],"hx":true,"yr":2,"pearls":["Sudden severe seborrheic dermatitis can be an early HIV clue","Infantile form is self-limited","Dandruff is the mild scalp form"],"source_ref":"https://dermnetnz.org/topics/seborrhoeic-dermatitis"},
{"id":"nwd31","subj":"Multisystem / Mixed","bw":["Well-demarcated scarring plaques on the face and scalp","Follicular plugging with central atrophy","Photosensitive with permanent hair loss","Usually negative ANA"],"ans":"Discoid Lupus Erythematosus","d":["Plaque Psoriasis","Subacute Cutaneous Lupus Erythematosus"],"tp":"Chronic cutaneous lupus with interface dermatitis. Sun protection, topical steroids and hydroxychloroquine; about 5-10% progress to systemic lupus.","ww":{"Plaque Psoriasis":"Photosensitive annular polycyclic eruption with anti-Ro antibodies and no scarring.","Subacute Cutaneous Lupus Erythematosus":"Silvery scaly plaques without follicular plugging or scarring alopecia."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"immunology","tags":["dermatology","lupus","autoimmune"],"hx":true,"yr":2,"pearls":["Causes scarring alopecia unlike alopecia areata","Lesions heal with atrophy and dyspigmentation","Biopsy shows interface dermatitis with mucin"],"source_ref":"https://dermnetnz.org/topics/discoid-lupus-erythematosus"},
{"id":"nwd32","subj":"Multisystem / Mixed","bw":["Hypopigmented anesthetic patch with thickened peripheral nerves","Exposure to armadillos or endemic regions","Infection prefers cooler body areas","Acid-fast bacilli on skin smear"],"ans":"Leprosy","d":["Cutaneous Leishmaniasis","Tinea Versicolor"],"tp":"Mycobacterium leprae (obligate intracellular, cooler skin). Tuberculoid (Th1) disease is paucibacillary; lepromatous (Th2) is multibacillary with leonine facies. Treat with dapsone and rifampin plus clofazimine for multibacillary disease.","ww":{"Cutaneous Leishmaniasis":"Ulcerating papule on the face after sandfly bite in the Middle East, with amastigotes.","Tinea Versicolor":"Scaly hypopigmented macules with normal sensation and hyphae/yeasts on KOH."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"microbiology","tags":["dermatology","mycobacteria","leprosy"],"hx":true,"yr":2,"pearls":["Tuberculoid: strong Th1, few bacilli; lepromatous: weak cellular response, many bacilli","Erythema nodosum leprosum is a type III reaction","Dapsone requires G6PD check"],"source_ref":"https://dermnetnz.org/topics/leprosy"},
{"id":"nwd33","subj":"Multisystem / Mixed","bw":["Rapidly growing violaceous nodule on the face of an older adult","Sun exposure and immunosuppression","Cytokeratin 20 perinuclear dot staining","Polyomavirus DNA in tumor"],"ans":"Merkel Cell Carcinoma","d":["Basal Cell Carcinoma","Cutaneous Squamous Cell Carcinoma"],"tp":"Aggressive neuroendocrine skin cancer linked to Merkel cell polyomavirus and UV. Treat with wide excision, sentinel node evaluation and radiation; PD-1 inhibitors (avelumab, pembrolizumab) are used for advanced disease.","ww":{"Basal Cell Carcinoma":"Pearly telangiectatic papule that grows slowly and rarely metastasizes.","Cutaneous Squamous Cell Carcinoma":"Ulcerating keratotic lesion in sun-damaged skin from actinic precursors."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":3,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","neuroendocrine","skin-cancer"],"hx":true,"yr":2,"pearls":["Small round blue cells resemble small-cell lung cancer but CK20-positive/TTF-1-negative","High local recurrence and nodal metastasis rate","More common in transplant recipients and CLL"],"source_ref":"https://dermnetnz.org/topics/merkel-cell-carcinoma"},
{"id":"nwd34","subj":"Multisystem / Mixed","bw":["Firm brown papule on the leg of a young woman","Dimples inward when pinched","Prior insect bite or shaving trauma","Benign spindle-cell proliferation"],"ans":"Dermatofibroma","d":["Melanoma","Seborrheic Keratosis"],"tp":"Common benign fibrohistiocytic lesion. Diagnose clinically by the dimple (Fitzpatrick) sign; no treatment needed unless symptomatic or atypical.","ww":{"Melanoma":"Asymmetric pigmented lesion with irregular border and color variation.","Seborrheic Keratosis":"Waxy stuck-on plaque with horn cysts."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","benign-neoplasm"],"hx":true,"yr":2,"pearls":["Fitzpatrick (dimple) sign is classic","Excise only if diagnosis uncertain","Multiple eruptive lesions occur in immunosuppression"],"source_ref":"https://dermnetnz.org/topics/dermatofibroma"},
{"id":"nwo01","subj":"Multisystem / Mixed","bw":["Gradual painless loss of peripheral vision in an older Black patient","Increased cup-to-disc ratio","Elevated intraocular pressure on tonometry","Family history in first-degree relatives"],"ans":"Primary Open-Angle Glaucoma","d":["Acute Angle-Closure Glaucoma","Age-Related Macular Degeneration"],"tp":"Optic neuropathy from impaired trabecular outflow. First-line therapy is a topical prostaglandin analog (latanoprost); alternatives include beta-blockers, alpha-agonists and carbonic anhydrase inhibitors. Laser trabeculoplasty is an option.","ww":{"Acute Angle-Closure Glaucoma":"Painful red eye with mid-dilated fixed pupil and halos.","Age-Related Macular Degeneration":"Central vision loss with drusen and metamorphopsia."},"exams":["step1","step2","step3","comlex1","comlex2","shelf_fm"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["ophthalmology","glaucoma"],"hx":true,"yr":2,"pearls":["Leading cause of irreversible blindness worldwide","Prostaglandin analogs can darken iris and lengthen lashes","Timolol is contraindicated in asthma and bradycardia"],"source_ref":"https://medlineplus.gov/glaucoma.html"},
{"id":"nwo02","subj":"Multisystem / Mixed","bw":["Sudden flashes and a shower of floaters","Curtain-like shadow over the visual field","Painless unilateral vision loss","High myopia or recent cataract surgery"],"ans":"Retinal Detachment","d":["Central Retinal Artery Occlusion","Vitreous Hemorrhage"],"tp":"Separation of neurosensory retina from the pigment epithelium. Emergency ophthalmology referral; repair with laser or cryopexy, pneumatic retinopexy, scleral buckle or vitrectomy.","ww":{"Central Retinal Artery Occlusion":"Painless sudden vision loss with a pale retina and cherry-red macula.","Vitreous Hemorrhage":"Painless dark floaters and red haze without a curtain, in a proliferative diabetic retinopathy patient."},"exams":["step1","step2","step3","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["ophthalmology","emergency"],"hx":true,"yr":2,"pearls":["Tobacco-dust (Shafer) sign suggests a tear","Risk factors: myopia, trauma, prior surgery, Marfan","Macula-off detachments have worse visual prognosis"],"source_ref":"https://eyewiki.org/Retinal_Detachment"},
{"id":"nwo03","subj":"Multisystem / Mixed","bw":["Sudden painless monocular blurring in a hypertensive patient","Diffuse retinal hemorrhages in all quadrants","Optic disc edema with engorged tortuous venules","\"Blood and thunder\" fundus"],"ans":"Central Retinal Vein Occlusion","d":["Central Retinal Artery Occlusion","Retinal Detachment"],"tp":"Venous outflow obstruction with macular edema and neovascular complications. Treat with intravitreal anti-VEGF agents and address hypertension, diabetes, glaucoma and hypercoagulability.","ww":{"Central Retinal Artery Occlusion":"Pale retina with cherry-red fovea from an embolic source.","Retinal Detachment":"Flashes and a curtain-like field defect."},"exams":["step2","comlex2","shelf_im"],"baseDifficulty":3,"questionType":"buzzword_dx","source":"pathology","tags":["ophthalmology","vascular"],"hx":true,"yr":2,"pearls":["Risk factors: hypertension, diabetes, glaucoma, hyperviscosity","Neovascular glaucoma can follow ischemic occlusion","Retinal artery occlusion needs stroke/embolic workup"],"source_ref":"https://eyewiki.org/Central_Retinal_Vein_Occlusion"},
{"id":"nwo04","subj":"Multisystem / Mixed","bw":["Gradual central vision loss in an elderly smoker","Drusen on fundus exam","Straight lines appear wavy on the Amsler grid","Peripheral vision preserved"],"ans":"Age-Related Macular Degeneration","d":["Primary Open-Angle Glaucoma","Cataract"],"tp":"Leading cause of vision loss in the elderly. Dry form: AREDS2 vitamins for intermediate disease. Wet (neovascular) form: intravitreal anti-VEGF injections (bevacizumab, ranibizumab, aflibercept).","ww":{"Primary Open-Angle Glaucoma":"Peripheral field loss with high intraocular pressure and optic disc cupping.","Cataract":"Gradual diffuse blurring with glare and lens opacity."},"exams":["step1","step2","comlex1","comlex2","shelf_fm"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["ophthalmology","macula"],"hx":true,"yr":2,"pearls":["Smoking is the main modifiable risk factor","Wet AMD causes most severe vision loss","Metamorphopsia and central scotoma are classic"],"source_ref":"https://medlineplus.gov/maculardegeneration.html"},
{"id":"nwo05","subj":"Multisystem / Mixed","bw":["Gradual painless blurring with glare from headlights","Opacified lens on slit-lamp exam","Diabetes or long-term steroid use","Absent red reflex in an infant needs urgent evaluation"],"ans":"Cataract","d":["Primary Open-Angle Glaucoma","Age-Related Macular Degeneration"],"tp":"Lens opacity from aging, UV, steroids, diabetes, galactosemia, trauma or radiation. Treat with surgical phacoemulsification and intraocular lens implantation when function is impaired.","ww":{"Primary Open-Angle Glaucoma":"Peripheral loss with a cupped optic nerve.","Age-Related Macular Degeneration":"Central loss with drusen and wavy lines."},"exams":["step1","step2","comlex1","comlex2","shelf_fm"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["ophthalmology","lens"],"hx":true,"yr":2,"pearls":["Sorbitol accumulation causes lens swelling in diabetics","Congenital cataract needs early surgery to prevent amblyopia","Galactosemia causes cataracts through galactitol"],"source_ref":"https://medlineplus.gov/cataract.html"},
{"id":"nwo06","subj":"Multisystem / Mixed","bw":["Progressive night blindness in a young adult","Tunnel vision","Bone-spicule pigment clumps on the peripheral retina","Abnormal electroretinogram"],"ans":"Retinitis Pigmentosa","d":["Age-Related Macular Degeneration","Retinal Detachment"],"tp":"Inherited photoreceptor degeneration (rods first). Visual field loss is progressive; vitamin A and low-vision rehabilitation are supportive, and gene therapy exists for RPE65 disease. Associated syndromes include Usher and abetalipoproteinemia.","ww":{"Age-Related Macular Degeneration":"Central vision loss in an elderly patient with drusen.","Retinal Detachment":"Sudden curtain over the field with flashes."},"exams":["step1","comlex1"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"genetics","tags":["ophthalmology","genetics","retina"],"hx":true,"yr":2,"pearls":["Usher syndrome combines RP with sensorineural deafness","Abetalipoproteinemia causes retinitis pigmentosa from vitamin E/A deficiency","Peripheral rods are lost before central cones"],"source_ref":"https://eyewiki.org/Retinitis_Pigmentosa"},
{"id":"nwo07","subj":"Multisystem / Mixed","bw":["Watery discharge with red eye after a cold","Tender preauricular lymph node","Follicular reaction of the lower lid","Spread through a household or school"],"ans":"Viral Conjunctivitis","d":["Bacterial Conjunctivitis","Allergic Conjunctivitis"],"tp":"Usually adenovirus; self-limited over 1-3 weeks. Supportive care with cool compresses and artificial tears; strict hand hygiene because it is highly contagious.","ww":{"Bacterial Conjunctivitis":"Thick purulent discharge with matted lids on waking.","Allergic Conjunctivitis":"Bilateral intense itching with stringy mucus and cobblestone papillae."},"exams":["step1","step2","comlex1","comlex2","shelf_fm","shelf_peds"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"microbiology","tags":["ophthalmology","conjunctivitis","adenovirus"],"hx":true,"yr":2,"pearls":["Pharyngoconjunctival fever combines fever, sore throat and red eyes","Antibiotics do not help viral disease","Contact lens wearers with pain need a keratitis workup"],"source_ref":"https://medlineplus.gov/pinkeye.html"},
{"id":"nwo08","subj":"Multisystem / Mixed","bw":["Bilateral intense itching and watery tearing","Chemosis and stringy white discharge","Seasonal pollen exposure with rhinitis","Cobblestone papillae under the upper lid"],"ans":"Allergic Conjunctivitis","d":["Viral Conjunctivitis","Bacterial Conjunctivitis"],"tp":"Type I hypersensitivity. Avoid allergens and use cold compresses; topical antihistamine/mast-cell stabilizers (olopatadine, ketotifen) are effective. Vernal and atopic keratoconjunctivitis may need steroids.","ww":{"Viral Conjunctivitis":"Watery discharge with preauricular lymphadenopathy and a recent URI.","Bacterial Conjunctivitis":"Mucopurulent discharge and crusting with unilateral onset."},"exams":["step1","step2","comlex1","comlex2","shelf_fm"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"immunology","tags":["ophthalmology","allergy"],"hx":true,"yr":2,"pearls":["Itching is the defining symptom","Giant papillary conjunctivitis occurs with contact lenses","Oral antihistamines can dry the eye"],"source_ref":"https://medlineplus.gov/pinkeye.html"},
{"id":"nwo09","subj":"Multisystem / Mixed","bw":["Painful red eye with a branching corneal lesion","Dendritic ulcer on fluorescein staining","Reduced corneal sensation","Prior cold sores"],"ans":"Herpes Simplex Keratitis","d":["Corneal Abrasion","Bacterial Conjunctivitis"],"tp":"Recurrent HSV-1 infection of the cornea. Treat with topical trifluridine or oral acyclovir/valacyclovir; topical steroids alone are dangerous. Stromal disease can cause scarring and blindness.","ww":{"Corneal Abrasion":"Linear scratch after trauma with sharp fluorescein uptake.","Bacterial Conjunctivitis":"Mucopurulent discharge with a normal cornea."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"microbiology","tags":["ophthalmology","HSV","cornea"],"hx":true,"yr":2,"pearls":["Latent virus resides in the trigeminal ganglion","Herpes zoster ophthalmicus shows pseudodendrites and Hutchinson sign","Never use steroid drops without ophthalmology input"],"source_ref":"https://medlineplus.gov/eyeinjuries.html"},
{"id":"nwo10","subj":"Multisystem / Mixed","bw":["Severe eye pain and tearing after a fingernail scratch","Foreign-body sensation with photophobia","Linear fluorescein uptake under cobalt-blue light","Contact lens wearer with sudden pain"],"ans":"Corneal Abrasion","d":["Herpes Simplex Keratitis","Acute Angle-Closure Glaucoma"],"tp":"Epithelial defect of the cornea. Treat with topical antibiotic ointment or drops (fluoroquinolone with Pseudomonas coverage for contact lens wearers); avoid eye patching; topical anesthetics only in the ED, not for home use.","ww":{"Herpes Simplex Keratitis":"Branching dendritic ulcer after cold sore.","Acute Angle-Closure Glaucoma":"Mid-dilated fixed pupil with halos and nausea."},"exams":["step2","step3","comlex2","shelf_fm"],"baseDifficulty":1,"questionType":"management","source":"clinical_medicine","tags":["ophthalmology","trauma","emergency"],"hx":true,"yr":2,"pearls":["Evert the lid to find retained foreign bodies","Prolonged topical anesthetic use delays healing","Rust ring suggests iron foreign body"],"source_ref":"https://medlineplus.gov/eyeinjuries.html"},
{"id":"nwo11","subj":"Multisystem / Mixed","bw":["Painless firm nodule in the upper eyelid","Chronic granulomatous inflammation of a blocked meibomian gland","No redness of the lid margin","Persisting for weeks after a tender bump"],"ans":"Chalazion","d":["Hordeolum","Preseptal Cellulitis"],"tp":"Treat with warm compresses and lid massage; refer for incision or steroid injection if persistent. A recurrent lesion should be biopsied to exclude sebaceous carcinoma.","ww":{"Hordeolum":"Acute painful red pustule at the lid margin from staphylococcal infection of a gland.","Preseptal Cellulitis":"Diffuse lid swelling with fever and normal eye movements."},"exams":["step2","comlex2","shelf_fm"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["ophthalmology","eyelid"],"hx":true,"yr":2,"pearls":["External hordeolum involves Zeis or Moll glands; internal involves meibomian glands","Chalazion is sterile lipogranuloma","Recurrent lesions in older adults need biopsy"],"source_ref":"https://medlineplus.gov/eyeinjuries.html"},
{"id":"nwo12","subj":"Multisystem / Mixed","bw":["Painful red swelling below the medial canthus","Epiphora and purulent discharge on pressing the sac","Chronic nasolacrimal duct obstruction","Infant or older woman"],"ans":"Dacryocystitis","d":["Chalazion","Orbital Cellulitis"],"tp":"Infection of the lacrimal sac, usually S. aureus or streptococci. Treat with warm compresses and systemic antibiotics; definitive dacryocystorhinostomy for chronic obstruction.","ww":{"Chalazion":"Painless firm eyelid nodule from meibomian gland blockage.","Orbital Cellulitis":"Proptosis and painful eye movements with fever."},"exams":["step2","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["ophthalmology","lacrimal"],"hx":true,"yr":2,"pearls":["Congenital nasolacrimal duct obstruction often resolves by 12 months","Dacryoadenitis involves the lateral upper lid","Orbital extension needs imaging and IV antibiotics"],"source_ref":"https://eyewiki.org/Dacryocystitis"},
{"id":"nwo13","subj":"Multisystem / Mixed","bw":["Transient painless curtain over one eye lasting minutes","Complete recovery of vision","Carotid bruit in a smoker","Retinal artery embolus (Hollenhorst plaque)"],"ans":"Amaurosis Fugax","d":["Retinal Detachment","Optic Neuritis"],"tp":"Transient monocular visual loss from retinal ischemia, usually carotid atherosclerosis. Evaluate as a TIA with carotid imaging, antiplatelet and statin therapy and risk-factor control; consider giant cell arteritis in patients over 50.","ww":{"Retinal Detachment":"Persistent curtain defect with flashes and floaters.","Optic Neuritis":"Painful eye movements and a relative afferent pupillary defect in a young woman."},"exams":["step2","step3","comlex2","shelf_neuro","shelf_im"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"clinical_medicine","tags":["ophthalmology","TIA","carotid"],"hx":true,"yr":2,"pearls":["Ipsilateral carotid is the usual source","Check ESR/CRP in patients over 50","Treat as stroke equivalent"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/?term=amaurosis+fugax+statpearls"},
{"id":"nwo14","subj":"Multisystem / Mixed","bw":["Copper-wire arterioles with arteriovenous nicking","Flame-shaped hemorrhages and cotton-wool spots","Optic disc swelling in malignant hypertension","Long-standing uncontrolled blood pressure"],"ans":"Hypertensive Retinopathy","d":["Diabetic Retinopathy","Central Retinal Vein Occlusion"],"tp":"Retinal vascular damage from chronic hypertension. Grade IV (papilledema) indicates hypertensive emergency and needs urgent blood pressure reduction.","ww":{"Diabetic Retinopathy":"Dot-blot hemorrhages and neovascularization in a diabetic.","Central Retinal Vein Occlusion":"Unilateral disc edema and diffuse hemorrhages."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["ophthalmology","hypertension"],"hx":true,"yr":2,"pearls":["Fundoscopy is the only direct view of small vessels","Papilledema marks malignant hypertension","Flame hemorrhages lie in the nerve fiber layer"],"source_ref":"https://eyewiki.org/Hypertensive_Retinopathy"},
{"id":"nwo15","subj":"Multisystem / Mixed","bw":["Progressive hearing loss in a young woman that worsens during pregnancy","Normal tympanic membrane","Hears better in noisy surroundings","Rinne negative with Weber lateralizing to the affected ear"],"ans":"Otosclerosis","d":["Sudden Sensorineural Hearing Loss","Cholesteatoma"],"tp":"Abnormal bone remodeling fixes the stapes footplate causing conductive hearing loss. Treat with stapedectomy or hearing aids. Reddish flush through the tympanic membrane (Schwartze sign) may be seen.","ww":{"Sudden Sensorineural Hearing Loss":"Abrupt unilateral loss over hours with sensorineural pattern.","Cholesteatoma":"Pearly white mass in the middle ear with foul drainage."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["ENT","hearing"],"hx":true,"yr":2,"pearls":["Autosomal dominant with incomplete penetrance","Paracusis of Willis: better hearing in noise","Fenestration of stapes is curative in many patients"],"source_ref":"https://www.nidcd.nih.gov/health/otosclerosis"},
{"id":"nwo16","subj":"Multisystem / Mixed","bw":["Gradual bilateral high-frequency hearing loss in an elderly patient","Difficulty understanding speech in noisy rooms","Loss of cochlear hair cells at the base","Symmetric sensorineural pattern"],"ans":"Presbycusis","d":["Otosclerosis","Menière Disease"],"tp":"Age-related sensorineural hearing loss. Treat with hearing aids, assistive devices and communication strategies; cochlear implants for severe loss. Untreated loss is linked to cognitive decline and isolation.","ww":{"Otosclerosis":"Conductive loss with stapes fixation in young adults.","Menière Disease":"Episodic vertigo, tinnitus and fluctuating low-frequency loss."},"exams":["step1","step2","comlex1","comlex2","shelf_fm"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["ENT","geriatrics","hearing"],"hx":true,"yr":2,"pearls":["Basal cochlear hair cells encode high frequencies","Screen older adults with whispered voice or audiometry","Noise exposure accelerates the loss"],"source_ref":"https://medlineplus.gov/ency/article/001045.htm"},
{"id":"nwo17","subj":"Multisystem / Mixed","bw":["Muffled ear evolving over hours to 3 days","Waking up with a muffled ear","No conductive component","Often no identifiable cause"],"ans":"Sudden Sensorineural Hearing Loss","d":["Otosclerosis","Cerumen Impaction"],"tp":"Defined as at least 30 dB loss across three frequencies within 72 hours. Urgent audiometry and oral corticosteroids; obtain MRI to exclude vestibular schwannoma and consider autoimmune or infectious causes.","ww":{"Otosclerosis":"Gradual conductive loss in a young woman.","Cerumen Impaction":"Reversible conductive loss with an occluded canal on otoscopy."},"exams":["step2","step3","comlex2"],"baseDifficulty":3,"questionType":"management","source":"clinical_medicine","tags":["ENT","emergency","hearing"],"hx":true,"yr":2,"pearls":["Consider it an otologic emergency","Weber lateralizes away from the affected ear","MRI looks for retrocochlear lesion"],"source_ref":"https://www.nidcd.nih.gov/health/sudden-deafness"},
{"id":"nwo18","subj":"Multisystem / Mixed","bw":["Chronic ear drainage with foul odor","White pearly mass behind the tympanic membrane","Conductive hearing loss after recurrent otitis","Retraction pocket of the pars flaccida"],"ans":"Cholesteatoma","d":["Otosclerosis","Acute Otitis Externa"],"tp":"Keratinizing squamous epithelium in the middle ear that erodes ossicles and bone. Requires surgical excision; complications include facial nerve palsy, labyrinthine fistula, meningitis and brain abscess.","ww":{"Otosclerosis":"Hearing loss with normal ear drum in a young woman.","Acute Otitis Externa":"Painful canal with tragal tenderness and swimming history."},"exams":["step2","comlex2","shelf_surg"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["ENT","otitis","surgery"],"hx":true,"yr":2,"pearls":["Does not respond to antibiotic drops alone","Can erode into the lateral semicircular canal causing vertigo","Congenital forms appear behind an intact drum"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/?term=cholesteatoma+statpearls"},
{"id":"nwo19","subj":"Multisystem / Mixed","bw":["Postauricular swelling and erythema after untreated ear infection","Protruding auricle","Fever and ear pain in a toddler","Opacified mastoid air cells on CT"],"ans":"Acute Mastoiditis","d":["Acute Otitis Externa","Cholesteatoma"],"tp":"Suppurative spread from acute otitis media into the mastoid. Treat with IV antibiotics and tympanocentesis or mastoidectomy for abscess; CT identifies complications such as sigmoid sinus thrombosis.","ww":{"Acute Otitis Externa":"Pain on tugging the pinna with swimming history and intact middle ear.","Cholesteatoma":"Painless chronic drainage with a pearly mass."},"exams":["step2","comlex2","shelf_peds"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["ENT","pediatrics"],"hx":true,"yr":2,"pearls":["Complications include subperiosteal abscess, meningitis, venous sinus thrombosis","Bezold abscess tracks along the sternocleidomastoid","Most common in children under 2 years"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/?term=acute+mastoiditis+statpearls"},
{"id":"nwo20","subj":"Multisystem / Mixed","bw":["Nasal polyps with adult-onset asthma","Bronchospasm and rhinorrhea after ibuprofen","Chronic sinus disease with eosinophilia","Overproduction of cysteinyl leukotrienes"],"ans":"Aspirin-Exacerbated Respiratory Disease","d":["Churg-Strauss Vasculitis","Allergic Rhinitis"],"tp":"Triad of asthma, nasal polyps and NSAID hypersensitivity (Samter triad) caused by COX-1 inhibition shifting arachidonic acid to leukotrienes. Avoid NSAIDs; leukotriene modifiers and aspirin desensitization can help.","ww":{"Churg-Strauss Vasculitis":"Eosinophilia with asthma and mononeuritis multiplex.","Allergic Rhinitis":"Seasonal sneezing and itchy eyes without NSAID reaction."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"mechanism","source":"immunology","tags":["ENT","asthma","leukotrienes"],"hx":true,"yr":2,"pearls":["Zileuton or montelukast reduces leukotrienes","Acetaminophen is usually tolerated","Nasal polyps in a child suggest cystic fibrosis"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/?term=aspirin-exacerbated+respiratory+disease+statpearls"},
{"id":"nwo21","subj":"Multisystem / Mixed","bw":["Pain and swelling of the submandibular gland while eating","Stone in Wharton duct","Swelling resolves between meals","Calcium-rich sialoliths"],"ans":"Sialolithiasis","d":["Mumps","Pleomorphic Adenoma"],"tp":"Salivary duct stones usually in the submandibular gland. Treat with hydration, sialogogues (lemon drops), massage and NSAIDs; sialendoscopy or surgery for large stones; antibiotics if infected.","ww":{"Mumps":"Bilateral parotid swelling in an unvaccinated child.","Pleomorphic Adenoma":"Painless slowly enlarging parotid mass."},"exams":["step2","comlex2","shelf_surg"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["ENT","salivary"],"hx":true,"yr":2,"pearls":["Submandibular saliva is more mucous and alkaline","Obstructive parotitis causes swelling with meals","Dehydration increases risk"],"source_ref":"https://medlineplus.gov/ency/article/001039.htm"},
{"id":"nwo22","subj":"Multisystem / Mixed","bw":["Painless neck mass in a middle-aged nonsmoking man","Tonsillar or base-of-tongue lesion","p16 positive tumor","Multiple oral sexual partners"],"ans":"Oropharyngeal HPV-Related Cancer","d":["Laryngeal Squamous Cell Carcinoma","Nasopharyngeal Carcinoma"],"tp":"HPV-16-driven squamous cell carcinoma with a better prognosis than tobacco-related disease. Evaluate with panendoscopy and imaging; treat with chemoradiation or transoral surgery.","ww":{"Laryngeal Squamous Cell Carcinoma":"Hoarseness in a heavy smoker and drinker.","Nasopharyngeal Carcinoma":"Epstein-Barr virus-associated tumor of the fossa of Rosenmuller in Southeast Asians."},"exams":["step1","step2","comlex1","comlex2","shelf_surg"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["ENT","HPV","oncology"],"hx":true,"yr":2,"pearls":["E6 degrades p53 and E7 degrades Rb","p16 immunostaining is a surrogate for HPV","HPV vaccination prevents oropharyngeal HPV infection"],"source_ref":"https://www.cancer.gov/types/head-and-neck/head-neck-fact-sheet"},
{"id":"nwu02","subj":"Surgery","bw":["Gradual scrotal pain over days with fever","Dysuria and urethral discharge in a young sexually active man","Pain improves with scrotal elevation","Intact cremasteric reflex"],"ans":"Acute Epididymitis","d":["Testicular Torsion","Testicular Cancer"],"tp":"Under 35: Chlamydia and gonorrhea (ceftriaxone plus doxycycline). Over 35 or insertive anal sex: enteric organisms (fluoroquinolone/levofloxacin). Exclude torsion first when onset is sudden.","ww":{"Testicular Torsion":"Abrupt onset with absent cremasteric reflex and high-riding testis.","Testicular Cancer":"Painless hard testicular mass."},"exams":["step1","step2","comlex1","comlex2","shelf_surg"],"baseDifficulty":1,"questionType":"dx_to_tx","source":"clinical_medicine","tags":["urology","STI","scrotum"],"hx":true,"yr":2,"pearls":["Prehn sign: relief with elevation suggests epididymitis","In prepubertal boys consider reflux or anomalies","Mumps orchitis follows parotitis"],"source_ref":"https://www.cdc.gov/std/treatment-guidelines/epididymitis.htm"},
{"id":"nwu04","subj":"Surgery","bw":["Testicular mass in a toddler","Schiller-Duval bodies resembling glomeruli","Markedly elevated alpha-fetoprotein","Most common prepubertal testicular tumor"],"ans":"Yolk Sac Tumor","d":["Seminoma","Choriocarcinoma"],"tp":"Endodermal sinus tumor secretes AFP. Treat with orchiectomy and chemotherapy (BEP in advanced disease). AFP also tracks recurrence.","ww":{"Seminoma":"Uniform cells with fried-egg look and no AFP elevation.","Choriocarcinoma":"Hemorrhagic tumor with very high beta-hCG and early hematogenous spread."},"exams":["step1","comlex1","shelf_peds"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["urology","germ-cell","tumor-marker"],"hx":true,"yr":2,"pearls":["Same histology as ovarian yolk sac tumor","Mixed germ cell tumors are common in adults","AFP is the marker; hCG is normal"],"source_ref":"https://www.cancer.gov/types/testicular"},
{"id":"nwu06","subj":"Surgery","bw":["Older man with weak stream, hesitancy and nocturia","Smooth symmetrically enlarged prostate","Hypertrophy of the transition zone","Incomplete bladder emptying"],"ans":"Benign Prostatic Hyperplasia","d":["Prostate Cancer","Chronic Prostatitis"],"tp":"Alpha-1 blockers (tamsulosin) relieve symptoms quickly; 5-alpha-reductase inhibitors (finasteride) shrink the gland over months and lower PSA about 50%. TURP is for refractory or complicated disease.","ww":{"Prostate Cancer":"Hard asymmetric nodule in the peripheral zone with elevated PSA.","Chronic Prostatitis":"Pelvic pain, dysuria and boggy tender prostate."},"exams":["step1","step2","comlex1","comlex2","shelf_surg","shelf_fm"],"baseDifficulty":1,"questionType":"dx_to_tx","source":"pharmacology","tags":["urology","prostate","BPH"],"hx":true,"yr":2,"pearls":["Tamsulosin: orthostatic hypotension and floppy iris syndrome","Finasteride: gynecomastia and sexual dysfunction","Hyperplasia of stromal and glandular elements in the transition zone"],"source_ref":"https://medlineplus.gov/prostatediseases.html"},
{"id":"nwu07","subj":"Surgery","bw":["Hard irregular nodule on digital rectal exam","Peripheral zone tumor","Back pain with osteoblastic bone lesions","Elevated PSA"],"ans":"Prostate Adenocarcinoma","d":["Benign Prostatic Hyperplasia","Bladder Urothelial Carcinoma"],"tp":"Most common nonskin cancer in men. Spreads via Batson venous plexus to vertebrae. Gleason score guides risk; options include surveillance, prostatectomy, radiation and androgen deprivation (GnRH agonists plus antiandrogens).","ww":{"Benign Prostatic Hyperplasia":"Smooth enlargement with obstructive symptoms in the transition zone.","Bladder Urothelial Carcinoma":"Painless hematuria in a smoker with papillary tumor."},"exams":["step1","step2","step3","comlex1","comlex2","shelf_surg"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["urology","prostate","cancer"],"hx":true,"yr":2,"pearls":["PSA screening is individualized (shared decision-making) ages 55-69","Osteoblastic metastases raise alkaline phosphatase","Leuprolide initial flare can be blocked with flutamide/bicalutamide"],"source_ref":"https://www.cancer.gov/types/prostate/psa-fact-sheet"},
{"id":"nwu08","subj":"Surgery","bw":["Painless gross hematuria in an older smoker","Exposure to aniline dyes or rubber industry","Papillary filling defect on cystoscopy","Cyclophosphamide history"],"ans":"Bladder Urothelial Carcinoma","d":["Renal Cell Carcinoma","Schistosoma Squamous Cell Carcinoma"],"tp":"Most common bladder cancer in the United States. Diagnose by cystoscopy and transurethral resection; BCG immunotherapy for non-muscle-invasive disease; cystectomy for muscle invasion.","ww":{"Renal Cell Carcinoma":"Hematuria with flank mass and polycythemia; clear cells with Von Hippel-Lindau mutation.","Schistosoma Squamous Cell Carcinoma":"Squamous carcinoma in endemic Egypt after chronic Schistosoma haematobium infection."},"exams":["step1","step2","comlex1","comlex2","shelf_surg"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["urology","bladder","smoking"],"hx":true,"yr":2,"pearls":["Smoking is the strongest risk factor","Painless hematuria warrants cystoscopy in adults","Schistosoma haematobium leads to squamous cell carcinoma"],"source_ref":"https://www.cancer.gov/types/bladder"},
{"id":"nwu09","subj":"Surgery","bw":["Painful erection lasting more than 4 hours without sexual stimulation","Sickle cell disease patient","Trazodone or PDE-5 inhibitor use","Rigid shaft with soft glans"],"ans":"Priapism","d":["Peyronie Disease","Paraphimosis"],"tp":"Ischemic (low-flow) priapism is an emergency: aspirate blood and inject phenylephrine; surgical shunt if refractory. Non-ischemic (high-flow) follows trauma and is managed conservatively.","ww":{"Peyronie Disease":"Penile curvature with a palpable plaque.","Paraphimosis":"Retracted foreskin trapped behind the glans causing swelling."},"exams":["step2","comlex2","shelf_surg"],"baseDifficulty":2,"questionType":"management","source":"clinical_medicine","tags":["urology","emergency","sickle-cell"],"hx":true,"yr":2,"pearls":["Sickle cell is the classic childhood cause","Delay beyond 4-6 hours risks permanent erectile dysfunction","Intracavernosal phenylephrine is the alpha-agonist of choice"],"source_ref":"https://medlineplus.gov/penisdisorders.html"},
{"id":"nwu10","subj":"Surgery","bw":["Painful curved erection","Palpable fibrous plaque along the penile shaft","Middle-aged man with Dupuytren contracture","Trauma or microtears of the tunica albuginea"],"ans":"Peyronie Disease","d":["Priapism","Penile Fracture"],"tp":"Fibrous plaque formation in the tunica albuginea. Often self-limited early; treatment includes intralesional collagenase (Xiaflex), traction, and surgery for stable severe curvature.","ww":{"Priapism":"Persistent painful erection with ischemia.","Penile Fracture":"Sudden snap, detumescence and bruising during intercourse."},"exams":["step2","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["urology","penis"],"hx":true,"yr":2,"pearls":["Associated with Dupuytren contracture and diabetes","Collagenase clostridium histolyticum can be injected","Erectile dysfunction frequently coexists"],"source_ref":"https://medlineplus.gov/penisdisorders.html"},
{"id":"nwu11","subj":"Surgery","bw":["Severe perineal pain in a diabetic man","Crepitus and dusky scrotal skin","Rapid spread with fever and shock","Polymicrobial necrotizing infection"],"ans":"Fournier Gangrene","d":["Cellulitis","Epididymitis"],"tp":"Urologic emergency of necrotizing fasciitis of the perineum. Give broad-spectrum antibiotics (including anaerobes and MRSA coverage) with immediate surgical debridement. SGLT2 inhibitors are associated with rare cases.","ww":{"Cellulitis":"Localized erythema and warmth responding to cephalexin.","Epididymitis":"Gradual scrotal pain with urethral discharge."},"exams":["step1","step2","step3","comlex2","shelf_surg"],"baseDifficulty":2,"questionType":"management","source":"surgery_principles","tags":["urology","necrotizing","emergency"],"hx":true,"yr":2,"pearls":["Diabetes is the most common risk factor","Pain out of proportion is a warning sign","Imaging should never delay surgery"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/NBK549821/"},
{"id":"nwu12","subj":"Surgery","bw":["Scrotal swelling described as a bag of worms","Left-sided in most cases","Increases on standing and Valsalva","Infertility with low sperm count"],"ans":"Varicocele","d":["Hydrocele","Testicular Torsion"],"tp":"Dilated pampiniform plexus. The left testicular vein drains into the left renal vein at a right angle. A new right-sided or non-decompressing varicocele raises suspicion of retroperitoneal mass or renal tumor.","ww":{"Hydrocele":"Painless fluid collection that transilluminates.","Testicular Torsion":"Acute severe pain with high-riding testis."},"exams":["step1","step2","comlex1","comlex2","shelf_surg"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"anatomy","tags":["urology","scrotum","infertility"],"hx":true,"yr":2,"pearls":["Most common surgically correctable cause of male infertility","Left renal vein drainage explains left predominance","Treat with varicocelectomy or embolization if symptomatic or infertile"],"source_ref":"https://medlineplus.gov/testiculardisorders.html"},
{"id":"nwe01","subj":"Multisystem / Mixed","bw":["Patient is told the diagnosis and proposed procedure","Risks, benefits and alternatives including no treatment are disclosed","Decision must be voluntary and without coercion","Patient demonstrates understanding"],"ans":"Informed Consent Elements","d":["Implied Consent","Therapeutic Privilege"],"tp":"Requires disclosure, understanding, capacity and voluntariness. Use an interpreter when language differs. Consent may be withdrawn at any time. Surgeon performing the procedure should obtain consent.","ww":{"Implied Consent":"Emergency treatment of an unconscious patient assumes agreement.","Therapeutic Privilege":"Withholding information believed to be harmful - very rarely valid."},"exams":["step1","step2","step3","comlex1","comlex2","shelf_surg"],"baseDifficulty":1,"questionType":"management","source":"ethics","tags":["ethics","consent"],"hx":true,"yr":2,"pearls":["Understanding requires teach-back","Exceptions: emergency, waiver, incapacity, therapeutic privilege","Consent for minors generally comes from a parent"],"source_ref":"https://www.ama-assn.org/delivering-care/ethics/informed-consent"},
{"id":"nwe03","subj":"Multisystem / Mixed","bw":["Patient lacks capacity with no written directive","Healthcare proxy is first choice","Then spouse, adult children and parents","Asks what the patient would have chosen"],"ans":"Surrogate Decision-Maker Hierarchy","d":["Best Interest Standard","Court-Appointed Guardian"],"tp":"Use the patient stated wishes first (advance directive), then the appointed proxy; if none, a legally recognized surrogate in a statutory order (generally spouse, adult children, parents, siblings). Substituted judgment asks what the patient would choose.","ww":{"Best Interest Standard":"Applied when patient preferences are unknowable.","Court-Appointed Guardian":"Needed when family disputes cannot be resolved."},"exams":["step2","step3","comlex2","shelf_im"],"baseDifficulty":2,"questionType":"management","source":"ethics","tags":["ethics","surrogate"],"hx":true,"yr":2,"pearls":["Substituted judgment is preferred over best interest","Ethics consult helps with disputes","Hierarchy varies by state"],"source_ref":"https://www.ama-assn.org/delivering-care/ethics/informed-consent"},
{"id":"nwe04","subj":"Multisystem / Mixed","bw":["Patient with active tuberculosis refusing to inform contacts","Duty to report to public health authorities","Suspected child abuse","Imminent threat to an identifiable person"],"ans":"Confidentiality Exceptions","d":["Physician-Patient Privilege","Therapeutic Privilege"],"tp":"Confidentiality can be broken for legally mandated reporting (reportable diseases, child/elder abuse, gunshot wounds in many states) and a credible serious threat to an identifiable victim (Tarasoff). Disclose the minimum necessary.","ww":{"Physician-Patient Privilege":"Unrestricted sharing with relatives.","Therapeutic Privilege":"Withholding diagnosis to prevent distress."},"exams":["step1","step2","step3","comlex1","comlex2","shelf_psych","shelf_fm"],"baseDifficulty":1,"questionType":"management","source":"ethics","tags":["ethics","confidentiality"],"hx":true,"yr":2,"pearls":["Tarasoff duty: warn or protect","Reportable diseases include TB, syphilis, measles","HIPAA permits disclosures required by law"],"source_ref":"https://code-medical-ethics.ama-assn.org/ethics-opinions/confidentiality"},
{"id":"nwe05","subj":"Multisystem / Mixed","bw":["Infant with multiple bruises in different stages of healing","Retinal hemorrhages in an infant","Inconsistent explanation of injury","Physician has reasonable suspicion only"],"ans":"Mandatory Reporting of Child Abuse","d":["Waiting for Proof","Informing Only the Parents"],"tp":"Physicians are mandated reporters and need only reasonable suspicion, not proof, to report to child protective services. Reports made in good faith are immune from liability. Parental consent is not required and the physician should document objectively.","ww":{"Waiting for Proof":"Reporting only after a confession.","Informing Only the Parents":"Discussing suspicion only with the abusing caregiver and discharging."},"exams":["step1","step2","step3","comlex1","comlex2","shelf_peds"],"baseDifficulty":1,"questionType":"management","source":"ethics","tags":["ethics","child-abuse","mandatory-reporting"],"hx":true,"yr":2,"pearls":["Skeletal survey for children under 2 with suspicious injury","Admit the child if the home is unsafe","Report even if a parent denies"],"source_ref":"https://www.cdc.gov/child-abuse-neglect/about/index.html"},
{"id":"nwe06","subj":"Multisystem / Mixed","bw":["Teenager requesting contraception without parents","Treatment of sexually transmitted infections","Emancipated or married minor","Substance use treatment and prenatal care"],"ans":"Minor Consent Exceptions","d":["Parental Consent Required","Implied Consent"],"tp":"Minors may consent without parental permission for confidential reproductive and STI care, substance and mental health services (varies by state), and when emancipated. Life-threatening emergencies can be treated without consent.","ww":{"Parental Consent Required":"Routine surgery on a child.","Implied Consent":"Unconscious emergency patient."},"exams":["step1","step2","step3","comlex1","comlex2","shelf_peds"],"baseDifficulty":1,"questionType":"management","source":"ethics","tags":["ethics","adolescent","minors"],"hx":true,"yr":2,"pearls":["Rules vary by state, so confirm local law","Maintain confidentiality of adolescents","Emancipation: marriage, military, financial independence or court order"],"source_ref":"https://www.ama-assn.org/delivering-care/ethics/informed-consent"},
{"id":"nwe07","subj":"Multisystem / Mixed","bw":["Written instructions for care after loss of capacity","Living will and durable power of attorney for health care","Patient refuses intubation if terminally ill","Clinician must honor stated wishes"],"ans":"Advance Directive","d":["Do-Not-Resuscitate Order","Best Interest Standard"],"tp":"Living will states treatment preferences; healthcare proxy designates an agent. A valid directive is followed unless it conflicts with law. Patients can revoke it at any time. A DNR is a specific order, not a global limit on all care.","ww":{"Do-Not-Resuscitate Order":"Specific code-status order written by a physician.","Best Interest Standard":"Surrogate acts with no known patient wishes."},"exams":["step1","step2","step3","comlex1","comlex2","shelf_im"],"baseDifficulty":1,"questionType":"management","source":"ethics","tags":["ethics","end-of-life","advance-directive"],"hx":true,"yr":2,"pearls":["Discuss goals of care early","POLST is for seriously ill patients","DNR does not mean do not treat"],"source_ref":"https://medlineplus.gov/advancedirectives.html"},
{"id":"nwe08","subj":"Multisystem / Mixed","bw":["Wrong medication dose administered to a patient","Physician learns of the mistake","Patient suffered no obvious harm","Honesty required regardless of liability fear"],"ans":"Disclosure of Medical Error","d":["Document Only in Incident Report","Wait for Patient to Ask"],"tp":"Disclose errors promptly, honestly and empathetically to the patient (or surrogate), explain consequences and corrective steps, apologize and report through institutional systems. Do not alter the chart or blame others.","ww":{"Document Only in Incident Report":"Recording only in a separate report without telling the patient.","Wait for Patient to Ask":"Waiting for lawsuit threats."},"exams":["step1","step2","step3","comlex1","comlex2"],"baseDifficulty":1,"questionType":"management","source":"ethics","tags":["ethics","patient-safety","error"],"hx":true,"yr":2,"pearls":["Never alter the medical record","Apology laws exist in many states","Systems analysis prevents recurrence"],"source_ref":"https://code-medical-ethics.ama-assn.org/ethics-opinions/promoting-patient-safety"},
{"id":"nwe09","subj":"Multisystem / Mixed","bw":["Drug representative offers a free steak dinner","Pens, mugs and textbooks branded with product name","Physician prescribes the sponsor drug more often","Inexpensive gift of educational value"],"ans":"Gifts from Pharmaceutical Industry","d":["Accept Small Gifts","Conflict of Interest Disclosure"],"tp":"Gifts of any size can bias prescribing. Avoid accepting meals, trips or personal gifts; items must benefit patients or education and have minimal value. Disclose relationships when presenting or publishing.","ww":{"Accept Small Gifts":"Permitted if disclosed, educational and modest.","Conflict of Interest Disclosure":"Transparent reporting of relationships."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"management","source":"ethics","tags":["ethics","conflict-of-interest"],"hx":true,"yr":2,"pearls":["Sunshine Act requires industry payment reporting","Educational grants should go to institutions","Disclose conflicts of interest"],"source_ref":"https://www.ama-assn.org/delivering-care/ethics/gifts-physicians-industry"},
{"id":"nwe10","subj":"Multisystem / Mixed","bw":["Adult declines transfusion on religious grounds","Hemorrhage after trauma but patient is alert and capable","Signed advance card carried in wallet","Alternative therapies available"],"ans":"Jehovah Witness Blood Refusal","d":["Court Order Transfusion","Implied Consent"],"tp":"A capable adult may refuse blood even if death results. Respect the decision, offer alternatives (cell salvage, erythropoietin, volume expanders). For children, seek a court order if life-threatening and parents refuse.","ww":{"Court Order Transfusion":"Needed when a minor faces life-threatening bleeding and parents refuse.","Implied Consent":"Applies when the patient is unconscious and wishes unknown."},"exams":["step1","step2","step3","comlex1","comlex2","shelf_surg"],"baseDifficulty":1,"questionType":"management","source":"ethics","tags":["ethics","autonomy","refusal"],"hx":true,"yr":2,"pearls":["Autonomy outweighs beneficence in capable adults","Pregnant women retain the right to refuse","Explore which fractions the patient will accept"],"source_ref":"https://www.ama-assn.org/delivering-care/ethics/informed-consent"},
{"id":"nwe12","subj":"Multisystem / Mixed","bw":["Seven-year-old enrolled in a trial","Parent signs permission form","Child agrees in age-appropriate language","Dissent honored except if therapy is vital"],"ans":"Assent for Pediatric Research","d":["Informed Consent","Implied Consent"],"tp":"Parents provide permission; the child (typically over 7) provides assent. Teenagers should be involved in decisions. Refusal by the child is generally respected in nonbeneficial research.","ww":{"Informed Consent":"Capacity-based for adults.","Implied Consent":"Used in emergencies."},"exams":["step1","step2","comlex1","comlex2","shelf_peds"],"baseDifficulty":2,"questionType":"management","source":"ethics","tags":["ethics","research","pediatrics"],"hx":true,"yr":2,"pearls":["Institutional review board oversees research","Minimal-risk exceptions possible","Assent is not legally binding consent"],"source_ref":"https://www.ama-assn.org/delivering-care/ethics/informed-consent"},
{"id":"nwe13","subj":"Multisystem / Mixed","bw":["Family demands CPR for a patient with terminal metastatic cancer","Physician judges the intervention will not benefit","No obligation to provide non-beneficial care","Ethics consultation recommended"],"ans":"Medical Futility","d":["Autonomy","Beneficence"],"tp":"Physicians need not provide treatments that will not achieve the patient goals, but should communicate compassionately, seek ethics consultation and follow institutional policy. Offer palliative care.","ww":{"Autonomy":"Respecting patient decision.","Beneficence":"Acting in patient best interest."},"exams":["step1","step2","step3","comlex1","comlex2","shelf_im"],"baseDifficulty":2,"questionType":"management","source":"ethics","tags":["ethics","end-of-life","futility"],"hx":true,"yr":2,"pearls":["Hospice referral if prognosis under 6 months","Time-limited trials help","Request is not an obligation to comply"],"source_ref":"https://www.ama-assn.org/delivering-care/ethics/code-medical-ethics-overview"},
{"id":"nwe14","subj":"Multisystem / Mixed","bw":["Spanish-speaking patient and English-speaking physician","Family member offers to translate","Sensitive topics such as abuse require privacy","Accuracy and confidentiality needed"],"ans":"Use of Interpreter","d":["Child as Translator","Physician Using Limited Spanish"],"tp":"Use a trained medical interpreter (in person, phone or video) rather than family members, especially children. Address the patient directly. Hospital must provide language services under federal law.","ww":{"Child as Translator":"Accepting a minor child to relay bad news.","Physician Using Limited Spanish":"Using partial fluency in a serious conversation."},"exams":["step1","step2","step3","comlex1","comlex2"],"baseDifficulty":1,"questionType":"management","source":"ethics","tags":["ethics","communication","interpreter"],"hx":true,"yr":2,"pearls":["Ad hoc interpreters risk errors and omission","Look at the patient, not the interpreter","Title VI requires language access"],"source_ref":"https://www.ama-assn.org/delivering-care/ethics/code-medical-ethics-overview"},
{"id":"nwm03","subj":"Surgery","bw":["Epiphyseal lytic lesion at the distal femur in a young adult","Soap-bubble appearance","Multinucleated osteoclast-like cells","Locally aggressive"],"ans":"Giant Cell Tumor of Bone","d":["Osteosarcoma","Chondrosarcoma"],"tp":"Typically benign but locally aggressive and may recur. Treat with curettage and local adjuvant or resection; denosumab (RANKL inhibitor) can shrink unresectable tumors.","ww":{"Osteosarcoma":"Metaphyseal sunburst lesion in adolescents.","Chondrosarcoma":"Calcified cartilaginous tumor in the pelvis of older adults."},"exams":["step1","comlex1","shelf_surg"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["orthopedics","bone-tumor"],"hx":true,"yr":2,"pearls":["Occurs after growth plate closure","Rare lung metastases","Denosumab targets RANKL"],"source_ref":"https://www.cancer.gov/types/bone"},
{"id":"nwm04","subj":"Surgery","bw":["Bony outgrowth with a cartilage cap near the knee in an adolescent","Most common benign bone tumor","Growth stops at skeletal maturity","Multiple hereditary form: EXT1/EXT2"],"ans":"Osteochondroma","d":["Chondrosarcoma","Osteosarcoma"],"tp":"Exostosis with continuous medullary canal with the host bone. Usually observed; resect if symptomatic. Rapid growth in adulthood suggests malignant transformation to chondrosarcoma.","ww":{"Chondrosarcoma":"Malignant cartilage tumor of the pelvis or proximal femur.","Osteosarcoma":"Aggressive sunburst lesion."},"exams":["step1","comlex1","shelf_surg"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["orthopedics","bone-tumor","genetics"],"hx":true,"yr":2,"pearls":["Hereditary multiple exostoses is autosomal dominant","Metaphyseal location","Cap thickness over 1.5-2 cm in adults is worrisome"],"source_ref":"https://www.cancer.gov/types/bone"},
{"id":"nwm05","subj":"Surgery","bw":["Nighttime bone pain in a teenager","Dramatic relief with NSAIDs","Small radiolucent nidus with surrounding sclerosis","Femur or tibia cortex"],"ans":"Osteoid Osteoma","d":["Osteomyelitis","Osteosarcoma"],"tp":"Benign painful osteoid-forming tumor under 2 cm that produces prostaglandins. Aspirin or NSAIDs relieve pain; CT-guided radiofrequency ablation is curative.","ww":{"Osteomyelitis":"Fever, elevated ESR and sequestrum.","Osteosarcoma":"Large aggressive lesion with periosteal elevation."},"exams":["step1","comlex1","shelf_surg"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["orthopedics","bone-tumor"],"hx":true,"yr":2,"pearls":["Nidus under 2 cm distinguishes it from osteoblastoma","Pain is worse at night and relieved by NSAIDs","Can cause painful scoliosis"],"source_ref":"https://www.cancer.gov/types/bone"},
{"id":"nwm07","subj":"Pediatrics","bw":["Painless limp in a 5-year-old boy","Idiopathic avascular necrosis of the femoral head","Radiograph shows flattened dense femoral head","Pain referred to the knee"],"ans":"Legg-Calve-Perthes Disease","d":["Slipped Capital Femoral Epiphysis","Septic Arthritis"],"tp":"Avascular necrosis of the capital femoral epiphysis in children aged 4-8. Treatment aims to maintain hip range of motion and containment (bracing, osteotomy); outcome is better in younger children.","ww":{"Slipped Capital Femoral Epiphysis":"Obese adolescent with external rotation.","Septic Arthritis":"Febrile child with refusal to bear weight and elevated inflammatory markers."},"exams":["step1","step2","comlex1","comlex2","shelf_peds"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["orthopedics","pediatrics","hip"],"hx":true,"yr":2,"pearls":["More common in boys","MRI detects early disease","Sickle cell disease causes AVN too"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/?term=legg-calve-perthes+disease+statpearls"},
{"id":"nwm10","subj":"Surgery","bw":["Painful mass in the pelvis or proximal femur of an older adult","Calcified chondroid matrix with popcorn pattern","Slowly progressive","Malignant transformation of an osteochondroma"],"ans":"Chondrosarcoma","d":["Osteosarcoma","Osteochondroma"],"tp":"Malignant hyaline cartilage tumor, usually resistant to chemotherapy and radiation; treated by wide surgical resection.","ww":{"Osteosarcoma":"Adolescent with osteoid-producing tumor and elevated ALP.","Osteochondroma":"Benign adolescent exostosis with cartilage cap."},"exams":["step1","comlex1","shelf_surg"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["orthopedics","bone-tumor"],"hx":true,"yr":2,"pearls":["Second most common primary malignant bone tumor in adults","Chemoradiation resistant","Arises from enchondroma or osteochondroma"],"source_ref":"https://www.cancer.gov/types/bone"},
{"id":"nwb01","subj":"Multisystem / Mixed","bw":["Screening detects cancer earlier without changing death date","Survival appears longer after diagnosis","No true improvement in mortality","Compare age-specific mortality instead"],"ans":"Lead-Time Bias","d":["Length-Time Bias","Selection Bias"],"tp":"Earlier detection extends measured survival even when time of death is unchanged. Evaluate screening with disease-specific mortality in randomized trials.","ww":{"Length-Time Bias":"Screening preferentially finds slow-growing indolent tumors.","Selection Bias":"Study participants differ from the target population."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"mechanism","source":"biostatistics","tags":["biostatistics","bias","screening"],"hx":true,"yr":2,"pearls":["Survival time starts at diagnosis, not at onset of disease","Mortality is the unbiased endpoint","Length-time bias favors indolent disease"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/NBK557491/"},
{"id":"nwb02","subj":"Multisystem / Mixed","bw":["Screening program detects mostly slow-growing tumors","Aggressive cancers present between screens","Survival seems better in screened patients","Overestimates benefit of screening"],"ans":"Length-Time Bias","d":["Lead-Time Bias","Recall Bias"],"tp":"Periodic screening preferentially detects slowly progressive disease with longer preclinical phase. Randomized trials with mortality endpoints correct for it.","ww":{"Lead-Time Bias":"Diagnosis earlier without altering death date.","Recall Bias":"Cases remember exposures better than controls."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"mechanism","source":"biostatistics","tags":["biostatistics","bias","screening"],"hx":true,"yr":2,"pearls":["Interval cancers are fast-growing","Overdiagnosis is related","Use mortality, not survival"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/NBK557491/"},
{"id":"nwb03","subj":"Multisystem / Mixed","bw":["Hospital-based case-control study","Hospitalized controls have other illnesses","False association between two diseases","Type of selection bias"],"ans":"Berkson Bias","d":["Recall Bias","Confounding"],"tp":"Hospital controls have higher exposure rates than the general population, distorting the odds ratio. A subtype of selection bias; choose population controls.","ww":{"Recall Bias":"Cases remember exposures more accurately.","Confounding":"Third variable linked to both exposure and outcome."},"exams":["step1","comlex1"],"baseDifficulty":3,"questionType":"mechanism","source":"biostatistics","tags":["biostatistics","bias","selection"],"hx":true,"yr":2,"pearls":["Selection bias occurs when subject selection differs from the target group","Neyman bias is prevalence bias","Healthy worker effect is another selection bias"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/NBK557491/"},
{"id":"nwb07","subj":"Multisystem / Mixed","bw":["Positive trials are published more often","Meta-analysis overestimates treatment effect","Funnel plot asymmetry","Negative studies stay in the file drawer"],"ans":"Publication Bias","d":["Recall Bias","Lead-Time Bias"],"tp":"Studies with significant results are more likely published, skewing systematic reviews. Detect with funnel plots; trial registration reduces the problem.","ww":{"Recall Bias":"Cases remember exposures differently.","Lead-Time Bias":"Earlier diagnosis without survival gain."},"exams":["step1","comlex1"],"baseDifficulty":2,"questionType":"mechanism","source":"biostatistics","tags":["biostatistics","meta-analysis","bias"],"hx":true,"yr":2,"pearls":["Funnel plot asymmetry suggests missing studies","ClinicalTrials.gov registration helps","Heterogeneity is tested with I-squared"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/NBK557491/"},
{"id":"nwb08","subj":"Multisystem / Mixed","bw":["Same test used in two clinics","Sensitivity and specificity unchanged","Clinic serving a sicker population","True positives make up a larger share of positives"],"ans":"Positive Predictive Value and Prevalence","d":["Sensitivity","Specificity"],"tp":"PPV rises and NPV falls as prevalence increases, while sensitivity and specificity are intrinsic to the test. Screening low-prevalence populations yields many false positives.","ww":{"Sensitivity":"Proportion of diseased who test positive.","Specificity":"Proportion of healthy who test negative."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"mechanism","source":"biostatistics","tags":["biostatistics","PPV","prevalence"],"hx":true,"yr":2,"pearls":["PPV = TP / (TP + FP)","NPV = TN / (TN + FN)","Sensitivity and specificity do not change with prevalence"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/NBK557491/"},
{"id":"nwg02","subj":"Multisystem / Mixed","bw":["65-year-old woman never screened","Dual-energy x-ray absorptiometry of hip and spine","T-score of -2.5 or lower","Postmenopausal women under 65 with risk factors"],"ans":"Osteoporosis Screening","d":["Vitamin D Level","Serum Calcium"],"tp":"USPSTF recommends bone density screening for women 65 and older and younger postmenopausal women at increased risk. T-score of -2.5 or lower defines osteoporosis. First-line therapy is a bisphosphonate (alendronate).","ww":{"Vitamin D Level":"Not used to diagnose osteoporosis.","Serum Calcium":"Normal in primary osteoporosis."},"exams":["step2","step3","comlex2","shelf_fm","shelf_im"],"baseDifficulty":1,"questionType":"prevention","source":"clinical_medicine","tags":["geriatrics","osteoporosis","screening"],"hx":true,"yr":2,"pearls":["Alendronate: take upright with water, esophagitis risk","Denosumab is an alternative","Atypical femur fractures and jaw osteonecrosis are rare complications"],"source_ref":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/osteoporosis-screening"},
{"id":"nwg03","subj":"Multisystem / Mixed","bw":["Man aged 65 who ever smoked","One-time ultrasonography of the aorta","Dilation to 3.0 cm or greater","Elective repair at 5.5 cm"],"ans":"Abdominal Aortic Aneurysm Screening","d":["CT Angiography","Chest X-ray"],"tp":"USPSTF recommends one-time ultrasound screening in men 65-75 who have ever smoked. Repair at 5.5 cm or growth over 0.5 cm in 6 months or symptomatic.","ww":{"CT Angiography":"Reserved for symptomatic or surgical planning.","Chest X-ray":"Not used for screening."},"exams":["step2","step3","comlex2","shelf_surg","shelf_fm"],"baseDifficulty":1,"questionType":"prevention","source":"clinical_medicine","tags":["geriatrics","AAA","screening"],"hx":true,"yr":2,"pearls":["Smoking is the strongest risk factor","Rupture presents with pain, hypotension and pulsatile mass","Endovascular repair is an option"],"source_ref":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/abdominal-aortic-aneurysm-screening"},
{"id":"nwg04","subj":"Multisystem / Mixed","bw":["62-year-old with 30 pack-year smoking history","Quit 5 years ago","Annual low-dose chest CT","Screening ages 50-80"],"ans":"Lung Cancer Screening","d":["Chest X-ray","Sputum Cytology"],"tp":"USPSTF: annual low-dose CT for adults 50-80 with at least a 20 pack-year history who currently smoke or quit within 15 years. Stop if a health problem limits life expectancy or surgery.","ww":{"Chest X-ray":"Not effective for screening.","Sputum Cytology":"Insensitive and not recommended."},"exams":["step2","step3","comlex2","shelf_im","shelf_fm"],"baseDifficulty":1,"questionType":"prevention","source":"clinical_medicine","tags":["geriatrics","lung-cancer","screening"],"hx":true,"yr":2,"pearls":["Pack-years = packs per day x years smoked","Smoking cessation counseling accompanies screening","Do not screen with chest radiograph"],"source_ref":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/lung-cancer-screening"},
{"id":"nwg05","subj":"Multisystem / Mixed","bw":["Elderly woman found on the floor after slipping","Orthostatic hypotension and sedative use","Gait and balance impairment","Exercise and home safety evaluation"],"ans":"Fall Prevention in Older Adults","d":["Bed Rest","Hip Protectors Alone"],"tp":"Multifactorial interventions: exercise (balance, strength, tai chi), medication review (sedatives, antihypertensives), vitamin D if deficient, vision correction and home safety evaluation. Check orthostatic vitals.","ww":{"Bed Rest":"Promotes deconditioning.","Hip Protectors Alone":"Insufficient without risk-factor management."},"exams":["step2","step3","comlex2","shelf_fm"],"baseDifficulty":1,"questionType":"prevention","source":"clinical_medicine","tags":["geriatrics","falls","prevention"],"hx":true,"yr":2,"pearls":["Stop Beers-list drugs if possible","Timed Up and Go test screens gait","Hip fracture is a major complication"],"source_ref":"https://medlineplus.gov/falls.html"},
{"id":"nwg06","subj":"Multisystem / Mixed","bw":["List of potentially inappropriate medications in elderly","Anticholinergic antihistamines and long-acting benzodiazepines","Increases risk of falls and delirium","Deprescribing suggested"],"ans":"Beers Criteria","d":["STOPP Criteria","FRAX Score"],"tp":"American Geriatrics Society Beers Criteria identifies drugs to avoid or use with caution in older adults (first-generation antihistamines, benzodiazepines, sulfonylureas such as glyburide, muscle relaxants). Review medications regularly.","ww":{"STOPP Criteria":"European counterpart for potentially inappropriate prescribing.","FRAX Score":"Fracture risk calculator."},"exams":["step2","step3","comlex2","shelf_fm"],"baseDifficulty":2,"questionType":"management","source":"clinical_medicine","tags":["geriatrics","polypharmacy"],"hx":true,"yr":2,"pearls":["Avoid diphenhydramine in the elderly","Anticholinergic burden worsens cognition","Glyburide risks hypoglycemia"],"source_ref":"https://doi.org/10.1111/jgs.18372"},
{"id":"nwn01","subj":"Multisystem / Mixed","bw":["Bleeding gums and perifollicular hemorrhages in a malnourished patient","Corkscrew hairs","Poor wound healing and joint bleeding","Diet lacking fruits and vegetables"],"ans":"Scurvy","d":["Pellagra","Beriberi"],"tp":"Vitamin C deficiency impairs hydroxylation of proline and lysine in collagen synthesis. Treat with oral vitamin C. Typical in alcohol use disorder, restricted diets and the elderly.","ww":{"Pellagra":"Dermatitis, diarrhea and dementia from niacin deficiency.","Beriberi":"Neuropathy and heart failure from thiamine deficiency."},"exams":["step1","step2","comlex1","comlex2","shelf_peds"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"biochemistry","tags":["nutrition","vitamin-C","collagen"],"hx":true,"yr":2,"pearls":["Prolyl and lysyl hydroxylase need ascorbate and iron","Infantile scurvy: subperiosteal bleeding and pseudoparalysis","Vitamin C also aids iron absorption"],"source_ref":"https://medlineplus.gov/ency/article/000355.htm"},
{"id":"nwn02","subj":"Multisystem / Mixed","bw":["Photosensitive dermatitis in a Casal necklace distribution","Diarrhea","Dementia","Corn-based diet or carcinoid syndrome"],"ans":"Pellagra","d":["Scurvy","Beriberi"],"tp":"Niacin (B3) deficiency causes the 4 Ds (dermatitis, diarrhea, dementia, death). Causes include isoniazid use, Hartnup disease, carcinoid syndrome (tryptophan diverted to serotonin). Treat with niacin.","ww":{"Scurvy":"Perifollicular bleeding with bleeding gums.","Beriberi":"Wet or dry cardiac and neurologic disease with thiamine deficiency."},"exams":["step1","comlex1","shelf_im"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"biochemistry","tags":["nutrition","niacin"],"hx":true,"yr":2,"pearls":["Niacin synthesized from tryptophan","Niacin excess causes flushing (prostaglandin-mediated)","Casal necklace on sun-exposed neck"],"source_ref":"https://medlineplus.gov/ency/article/000342.htm"},
{"id":"nwn03","subj":"Multisystem / Mixed","bw":["Alcohol use disorder with peripheral neuropathy","High-output heart failure with edema","Polished-rice diet","Thiamine deficiency"],"ans":"Beriberi","d":["Scurvy","Pellagra"],"tp":"Thiamine (B1) is cofactor for pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase, transketolase, and branched-chain ketoacid dehydrogenase. Wet beriberi causes cardiac failure; dry beriberi causes neuropathy. Give thiamine BEFORE glucose in at-risk patients.","ww":{"Scurvy":"Collagen defect with gum bleeding.","Pellagra":"Dermatitis, diarrhea and dementia."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"biochemistry","tags":["nutrition","thiamine"],"hx":true,"yr":2,"pearls":["Wernicke-Korsakoff is the CNS form","Erythrocyte transketolase activity is reduced","Give thiamine before glucose"],"source_ref":"https://medlineplus.gov/ency/article/000339.htm"},
{"id":"nwa03","subj":"Surgery","bw":["Wrist drop after midshaft humerus fracture","Inability to extend wrist and fingers","Loss of sensation on dorsal first web space","Saturday night palsy"],"ans":"Radial Nerve Injury","d":["Median Nerve Injury","Ulnar Nerve Injury"],"tp":"Spiral groove injury spares triceps if lesion is distal. Supports the extensors of the wrist and fingers and supinator. Splint the wrist in extension; most recover spontaneously.","ww":{"Median Nerve Injury":"Ape hand and loss of thumb opposition.","Ulnar Nerve Injury":"Claw hand with fourth and fifth finger sensory loss."},"exams":["step1","step2","comlex1","comlex2","shelf_surg"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"anatomy","tags":["anatomy","nerve-injury","fracture"],"hx":true,"yr":2,"pearls":["Humeral shaft fracture is the classic cause","Axilla compression (crutches) injures it proximally with triceps weakness","Grip is weak because wrist cannot extend"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/?term=radial+nerve+injury+statpearls"},
{"id":"nwa04","subj":"Surgery","bw":["Foot drop with high-stepping gait","Fibular neck fracture or tight cast","Loss of sensation on the dorsum of the foot","Inability to evert or dorsiflex"],"ans":"Common Peroneal Nerve Injury","d":["Tibial Nerve Injury","L5 Radiculopathy"],"tp":"Superficial peroneal nerve everts the foot; deep peroneal dorsiflexes. Wraps around the fibular neck, making it vulnerable to trauma and compression. Treat with ankle-foot orthosis; consider surgical exploration.","ww":{"Tibial Nerve Injury":"Inability to plantarflex and loss of sole sensation.","L5 Radiculopathy":"Back pain radiating down the leg with inversion preserved."},"exams":["step1","step2","comlex1","comlex2","shelf_neuro"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"anatomy","tags":["anatomy","nerve-injury","foot-drop"],"hx":true,"yr":2,"pearls":["Crossed legs and casts are common causes","Inversion preserved distinguishes from L5 radiculopathy","Branch of the sciatic nerve"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/?term=common+peroneal+nerve+injury+statpearls"},
{"id":"nwa05","subj":"Surgery","bw":["Shoulder dislocation or surgical neck humerus fracture","Loss of arm abduction beyond 15 degrees","Flattened deltoid","Numb patch over the lateral shoulder"],"ans":"Axillary Nerve Injury","d":["Radial Nerve Injury","Rotator Cuff Tear"],"tp":"Axillary nerve (C5-C6) supplies deltoid and teres minor and passes through the quadrangular space. Injured with anterior glenohumeral dislocation or surgical neck fracture.","ww":{"Radial Nerve Injury":"Wrist drop with humeral shaft fracture.","Rotator Cuff Tear":"Positive drop-arm test with normal sensation over deltoid."},"exams":["step1","step2","comlex1","comlex2","shelf_surg"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"anatomy","tags":["anatomy","nerve-injury","shoulder"],"hx":true,"yr":2,"pearls":["Supraspinatus initiates abduction (first 15 degrees)","Check regimental badge sensation","Posterior cord branch"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/?term=axillary+nerve+injury+statpearls"},
{"id":"nwu15","subj":"Surgery","bw":["Fever, chills and perineal pain in a man","Dysuria with urinary retention","Exquisitely tender boggy prostate","E. coli on urine culture"],"ans":"Acute Bacterial Prostatitis","d":["Benign Prostatic Hyperplasia","Acute Epididymitis"],"tp":"Gentle exam only (no vigorous massage, which risks bacteremia). Treat with fluoroquinolone or TMP-SMX for 2-4 weeks (longer for chronic disease); admit if septic or retaining urine.","ww":{"Benign Prostatic Hyperplasia":"Gradual obstructive symptoms with a smooth firm nontender gland.","Acute Epididymitis":"Scrotal pain localized to the posterior testis with normal prostate."},"exams":["step1","step2","comlex2","shelf_surg"],"baseDifficulty":2,"questionType":"dx_to_tx","source":"microbiology","tags":["urology","prostate","infection"],"hx":true,"yr":2,"pearls":["Prostatic massage is contraindicated in the acute form","Chronic form needs prolonged antibiotics","Fluoroquinolones penetrate the prostate well"],"source_ref":"https://medlineplus.gov/prostatediseases.html"},
{"id":"nwu16","subj":"Surgery","bw":["Painful swollen glans in an uncircumcised man","Foreskin retracted and cannot be returned","Occurs after catheterization or exam","Constricting band behind the glans"],"ans":"Paraphimosis","d":["Phimosis","Priapism"],"tp":"Urologic emergency: reduce with lubrication, compression and manual reduction (osmotic agents such as granulated sugar may help); dorsal slit if this fails. Always replace the foreskin after catheter placement.","ww":{"Phimosis":"Foreskin cannot be retracted over the glans at all.","Priapism":"Painful prolonged erection lasting hours."},"exams":["step2","comlex2","shelf_surg","shelf_peds"],"baseDifficulty":2,"questionType":"management","source":"clinical_medicine","tags":["urology","emergency","penis"],"hx":true,"yr":2,"pearls":["Vascular compromise can cause glans necrosis","Phimosis is the opposite problem","Prevent by replacing the foreskin after Foley placement"],"source_ref":"https://medlineplus.gov/penisdisorders.html"},
{"id":"nwu17","subj":"Surgery","bw":["Older man unable to void with suprapubic pain","Palpable distended bladder","Started an anticholinergic or decongestant","Large post-void residual on bladder scan"],"ans":"Acute Urinary Retention","d":["Urge Incontinence","Urinary Tract Infection"],"tp":"Place a urethral catheter (suprapubic if impossible) and treat the cause (BPH, drugs, constipation, neurogenic). Watch for post-obstructive diuresis and hematuria after decompression.","ww":{"Urge Incontinence":"Sudden urgency with leakage and small voids.","Urinary Tract Infection":"Dysuria and frequency with fever and clear bladder scan."},"exams":["step1","step2","comlex2","shelf_surg"],"baseDifficulty":1,"questionType":"management","source":"clinical_medicine","tags":["urology","BPH","catheter"],"hx":true,"yr":2,"pearls":["BPH is the commonest cause in men","Check creatinine for obstructive uropathy","Postobstructive diuresis may need fluid replacement"],"source_ref":"https://www.niddk.nih.gov/health-information/urologic-diseases/urinary-retention"},
{"id":"nwe15","subj":"Multisystem / Mixed","bw":["Family asks to stop a ventilator in a dying patient","Physician hesitates because stopping feels different from not starting","Patient previously declined prolonged ventilator use","Comfort-focused care"],"ans":"Withdrawing Versus Withholding Life Support","d":["Euthanasia","Medical Futility"],"tp":"Ethically and legally equivalent: if a treatment may be refused, it may be withdrawn. Respect patient wishes, provide palliative sedation and symptom relief. Euthanasia involves actively causing death and differs.","ww":{"Euthanasia":"Deliberate injection to end life.","Medical Futility":"Declining a non-beneficial request."},"exams":["step1","step2","step3","comlex1","comlex2"],"baseDifficulty":2,"questionType":"management","source":"ethics","tags":["ethics","end-of-life"],"hx":true,"yr":2,"pearls":["No ethical difference between withholding and withdrawing","Opioids for dyspnea are acceptable even if respiration slows","Involve palliative care and chaplaincy"],"source_ref":"https://www.ama-assn.org/delivering-care/ethics/code-medical-ethics-overview"},
{"id":"nwe16","subj":"Multisystem / Mixed","bw":["Doctor declines to perform a procedure that violates personal beliefs","Patient needs timely care","Emergency exists with no other provider","Duty to refer"],"ans":"Conscientious Objection by Physician","d":["Patient Abandonment","Informed Refusal"],"tp":"A physician may decline for moral reasons if the patient is not harmed: disclose options, refer or transfer care promptly and never refuse in an emergency. Abandonment is unilateral termination of care without notice.","ww":{"Patient Abandonment":"Terminating care without arranging continuity.","Informed Refusal":"Patient declining recommended treatment."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"management","source":"ethics","tags":["ethics","professionalism"],"hx":true,"yr":2,"pearls":["Must not impose personal views","Provide emergency care regardless","Document the referral"],"source_ref":"https://www.ama-assn.org/delivering-care/ethics/code-medical-ethics-overview"},
{"id":"nwb09","subj":"Multisystem / Mixed","bw":["Two radiologists read the same films","Agreement exceeds chance","Value of 0.8 indicates strong concordance","Used for categorical ratings"],"ans":"Cohen Kappa","d":["Pearson Correlation","Standard Deviation"],"tp":"Kappa measures inter-rater agreement beyond chance (0 = chance, 1 = perfect). Pearson correlation measures linear association of continuous variables.","ww":{"Pearson Correlation":"Linear association between two continuous variables.","Standard Deviation":"Dispersion of values around a mean."},"exams":["step1","comlex1"],"baseDifficulty":3,"questionType":"mechanism","source":"biostatistics","tags":["biostatistics","reliability"],"hx":true,"yr":2,"pearls":["Corrects for agreement by chance","Values over 0.8 are very good","Reliability differs from validity"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/NBK557421/"},
{"id":"nwb10","subj":"Multisystem / Mixed","bw":["Vaccination coverage needed to stop sustained spread","Depends on the basic reproduction number","Measles requires about 95%","Protects those who cannot be vaccinated"],"ans":"Herd Immunity Threshold","d":["Attack Rate","Case Fatality Rate"],"tp":"Threshold = 1 - 1/R0. Higher R0 (measles about 12-18) needs higher coverage. Incomplete coverage allows outbreaks in pockets of the unvaccinated.","ww":{"Attack Rate":"Proportion of exposed who become ill.","Case Fatality Rate":"Proportion of cases that die."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"prevention","source":"biostatistics","tags":["biostatistics","vaccination","epidemiology"],"hx":true,"yr":2,"pearls":["R0 under 1 means the outbreak dies out","Measles is among the most contagious viruses","Vaccine hesitancy erodes herd immunity"],"source_ref":"https://www.cdc.gov/vaccines/vac-gen/immunity-types.htm"},
{"id":"nwb11","subj":"Multisystem / Mixed","bw":["Trial of a new drug shows excess bleeding","Event rate 3% versus 1% in controls","Reciprocal of the absolute risk increase","Patients treated for one additional adverse event"],"ans":"Number Needed to Harm","d":["Number Needed to Treat","Relative Risk"],"tp":"NNH = 1/ARI; here 1/0.02 = 50. Compare with NNT to weigh benefit against harm.","ww":{"Number Needed to Treat":"Reciprocal of absolute risk reduction.","Relative Risk":"Ratio of event rates between groups."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"mechanism","source":"biostatistics","tags":["biostatistics","harm"],"hx":true,"yr":2,"pearls":["ARI = treatment event rate minus control event rate","Large NNH is reassuring","Likelihood of being helped or harmed (LHH) compares them"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/NBK430713/"},
{"id":"nwo23","subj":"Multisystem / Mixed","bw":["Child with reduced vision in one eye despite normal exam","Strabismus or unequal refraction","Discovered at preschool screening","Cortical suppression of the weaker eye"],"ans":"Amblyopia","d":["Cataract","Retinoblastoma"],"tp":"Cortical visual development failure in the critical period (under about 8 years). Correct refractive error and treat by patching or atropine penalization of the better eye; early detection is essential.","ww":{"Cataract":"Leukocoria with absent red reflex requiring urgent surgery.","Retinoblastoma":"Opaque lens in infancy."},"exams":["step1","step2","comlex1","comlex2","shelf_peds"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["ophthalmology","pediatrics"],"hx":true,"yr":2,"pearls":["Most common cause of monocular vision loss in children","Red reflex screening in newborns","Occlusion therapy is time-sensitive"],"source_ref":"https://www.nei.nih.gov/learn-about-eye-health/eye-conditions-and-diseases/amblyopia-lazy-eye"},
{"id":"nwo24","subj":"Multisystem / Mixed","bw":["Headache worse in the morning with transient visual obscurations","Bilateral optic disc swelling with blurred margins","Increased intracranial pressure","Enlarged blind spot"],"ans":"Papilledema","d":["Optic Neuritis","Central Retinal Artery Occlusion"],"tp":"Bilateral disc swelling from raised intracranial pressure (tumor, IIH, venous sinus thrombosis). Neuroimaging first, then lumbar puncture if safe; vision is lost if untreated.","ww":{"Optic Neuritis":"Unilateral pain on eye movement with a relative afferent pupillary defect.","Central Retinal Artery Occlusion":"Sudden monocular blindness with pale retina."},"exams":["step1","step2","step3","comlex1","comlex2","shelf_neuro"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["ophthalmology","neurology","ICP"],"hx":true,"yr":2,"pearls":["Unilateral swelling is usually optic neuritis, not papilledema","Image before lumbar puncture","Acetazolamide treats idiopathic intracranial hypertension"],"source_ref":"https://eyewiki.org/Papilledema"},
{"id":"nwo25","subj":"Multisystem / Mixed","bw":["Painless neck mass in a man of Southeast Asian ancestry","Unilateral serous otitis media in an adult","Epstein-Barr virus DNA in plasma","Undifferentiated cells with lymphocytes"],"ans":"Nasopharyngeal Carcinoma","d":["Laryngeal Squamous Cell Carcinoma","Oropharyngeal HPV-Related Cancer"],"tp":"Arises in the fossa of Rosenmuller. EBV and diet (salted fish) are risk factors; treat with radiation plus chemotherapy. Adults with unilateral middle ear effusion need nasopharyngoscopy.","ww":{"Laryngeal Squamous Cell Carcinoma":"Hoarseness in smoker and drinker.","Oropharyngeal HPV-Related Cancer":"p16-positive tonsillar tumor in a nonsmoker."},"exams":["step1","step2","comlex1","comlex2"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"pathology","tags":["ENT","EBV","oncology"],"hx":true,"yr":2,"pearls":["Cervical lymph node metastasis is common at presentation","Cranial nerve palsies indicate skull-base invasion","Plasma EBV DNA tracks response"],"source_ref":"https://www.cancer.gov/types/head-and-neck/patient/adult/nasopharyngeal-treatment-pdq"},
{"id":"nwo26","subj":"Multisystem / Mixed","bw":["Rapidly spreading swelling of the floor of the mouth after dental extraction","Elevated tongue and drooling","Bilateral submandibular woody induration","Stridor risk"],"ans":"Ludwig Angina","d":["Peritonsillar Abscess","Sialolithiasis"],"tp":"Polymicrobial cellulitis of the submandibular, sublingual and submental spaces from molar infection. Secure the airway first, then IV antibiotics (ampicillin-sulbactam) and surgical drainage as needed.","ww":{"Peritonsillar Abscess":"Unilateral palatal bulge with uvular deviation and trismus.","Sialolithiasis":"Meal-related pain from duct stone."},"exams":["step2","step3","comlex2","shelf_surg"],"baseDifficulty":2,"questionType":"management","source":"clinical_medicine","tags":["ENT","airway","emergency"],"hx":true,"yr":2,"pearls":["Airway is priority number one","Usually odontogenic (second or third molars)","Descending mediastinitis is a feared complication"],"source_ref":"https://medlineplus.gov/dentalhealth.html"},
{"id":"nwo28","subj":"Multisystem / Mixed","bw":["Child with misaligned eyes","Asymmetric corneal light reflex (Hirschberg test)","Eye deviates on cover-uncover test","Risk of vision suppression"],"ans":"Strabismus","d":["Nystagmus","Retinoblastoma"],"tp":"Ocular misalignment; refer promptly because untreated strabismus causes amblyopia. Treat refractive error, patching and surgery. Constant deviation after 4 months is abnormal; new onset in a child needs retinal exam.","ww":{"Nystagmus":"Involuntary rhythmic eye oscillation.","Retinoblastoma":"White pupillary reflex with absent red reflex."},"exams":["step1","step2","comlex2","shelf_peds"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["ophthalmology","pediatrics"],"hx":true,"yr":2,"pearls":["Intermittent deviation under 4 months can be normal","Cover test detects tropia","Esotropia is more common in children"],"source_ref":"https://www.nei.nih.gov/learn-about-eye-health/eye-conditions-and-diseases/amblyopia-lazy-eye"},
{"id":"nwg07","subj":"Multisystem / Mixed","bw":["Elderly patient with unintentional weight loss and exhaustion","Slow gait and weak grip","Low physical activity","Vulnerable to minor stressors"],"ans":"Frailty Syndrome","d":["Delirium","Major Depression"],"tp":"Fried phenotype: weight loss, exhaustion, weakness, slow gait and low activity (3 or more). Treat with resistance exercise, protein and calorie optimization, medication review and advance care planning.","ww":{"Delirium":"Acute fluctuating inattention.","Major Depression":"Mood disorder with anhedonia."},"exams":["step2","step3","comlex2","shelf_fm"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"clinical_medicine","tags":["geriatrics","frailty"],"hx":true,"yr":2,"pearls":["Predicts falls, hospitalization and death","Exercise is the best intervention","Sarcopenia is a core component"],"source_ref":"https://medlineplus.gov/seniorshealth.html"},
{"id":"nwg08","subj":"Multisystem / Mixed","bw":["Constant dribbling in an older diabetic man","Weak stream and large post-void residual","Distended bladder on exam","Detrusor underactivity or outlet obstruction"],"ans":"Overflow Incontinence","d":["Stress Incontinence","Urge Incontinence"],"tp":"Chronic retention causes leakage. Treat the cause: relieve obstruction (alpha blocker for BPH), intermittent catheterization for neurogenic bladder, and review anticholinergic drugs.","ww":{"Stress Incontinence":"Leakage with cough or sneeze and normal residual.","Urge Incontinence":"Sudden urgency and detrusor overactivity."},"exams":["step2","comlex2","shelf_fm","shelf_obgyn"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"clinical_medicine","tags":["geriatrics","incontinence","urology"],"hx":true,"yr":2,"pearls":["Diabetic neuropathy causes atonic bladder","Post-void residual over 200 mL","Anticholinergics worsen retention"],"source_ref":"https://medlineplus.gov/urinaryincontinence.html"},
{"id":"nwg09","subj":"Multisystem / Mixed","bw":["Gradual loss of muscle mass and strength in the elderly","Slow walking speed","Low appendicular lean mass on DEXA","Reduced protein intake"],"ans":"Sarcopenia","d":["Hypothyroid Myopathy","Polymyalgia Rheumatica"],"tp":"Age-related loss of skeletal muscle. Prevent with resistance training, adequate protein and treatment of vitamin D deficiency; no drug is approved.","ww":{"Hypothyroid Myopathy":"Proximal weakness with elevated CK and cold intolerance.","Polymyalgia Rheumatica":"Morning stiffness of shoulders and hips with elevated ESR."},"exams":["step2","comlex2","shelf_fm"],"baseDifficulty":2,"questionType":"buzzword_dx","source":"clinical_medicine","tags":["geriatrics","muscle"],"hx":true,"yr":2,"pearls":["Resistance exercise is the most effective therapy","Contributes to falls and fractures","Diagnosed by strength and mass criteria"],"source_ref":"https://medlineplus.gov/seniorshealth.html"},
{"id":"nwd36","subj":"Multisystem / Mixed","bw":["Symmetric brown patches on the cheeks and forehead","Pregnant woman or oral contraceptive use","Worsens with sun exposure","Epidermal and dermal melanin"],"ans":"Melasma","d":["Vitiligo","Pityriasis Versicolor"],"tp":"Hormone- and UV-driven hyperpigmentation (the mask of pregnancy). Treat with sunscreen, hydroquinone, tretinoin and azelaic acid; often fades postpartum.","ww":{"Vitiligo":"Depigmented chalk-white patches from melanocyte loss.","Pityriasis Versicolor":"Scaly hypopigmented macules on the upper trunk."},"exams":["step2","comlex2","shelf_obgyn","shelf_fm"],"baseDifficulty":1,"questionType":"buzzword_dx","source":"pathology","tags":["dermatology","pigment","pregnancy"],"hx":true,"yr":2,"pearls":["Estrogen and progesterone stimulate melanocytes","Sun protection is essential","Recurs without maintenance"],"source_ref":"https://medlineplus.gov/skinconditions.html"},
{"id":"nwd37","subj":"Multisystem / Mixed","bw":["Superficial scaly crusted erosions on the scalp and trunk","Mouth spared","Nikolsky sign positive","Autoantibodies to desmoglein 1"],"ans":"Pemphigus Foliaceus","d":["Pemphigus Vulgaris","Bullous Pemphigoid"],"tp":"Superficial (subcorneal) acantholysis from anti-desmoglein-1 IgG, so blisters are fragile and mucosa is spared. Treat with corticosteroids and immunosuppressants. Endemic fogo selvagem occurs in Brazil.","ww":{"Pemphigus Vulgaris":"Deep flaccid blisters with oral erosions and anti-desmoglein 3.","Bullous Pemphigoid":"Tense bullae with linear IgG at the basement membrane."},"exams":["step1","comlex1"],"baseDifficulty":3,"questionType":"buzzword_dx","source":"immunology","tags":["dermatology","bullous","autoimmune"],"hx":true,"yr":2,"pearls":["Desmoglein 1 predominates in superficial epidermis","No mucosal lesions","Drugs such as penicillamine can trigger it"],"source_ref":"https://dermnetnz.org/topics/pemphigus-foliaceus"},
{"id":"nwm11","subj":"Surgery","bw":["Inversion injury with ankle pain after a sports fall","Bony tenderness at the posterior edge of the lateral malleolus","Unable to bear weight for four steps","Decision rule to limit radiographs"],"ans":"Ottawa Ankle Rules","d":["MRI of Ankle","Stress Test"],"tp":"Obtain ankle radiographs only if there is malleolar-zone pain plus bone tenderness at the posterior edge or tip of either malleolus, or inability to bear weight for four steps. Midfoot rules include the base of the fifth metatarsal and navicular.","ww":{"MRI of Ankle":"Not used to exclude fracture initially.","Stress Test":"Used for cardiac ischemia, not the ankle."},"exams":["step2","step3","comlex2","shelf_surg","shelf_fm"],"baseDifficulty":2,"questionType":"dx_to_workup","source":"clinical_medicine","tags":["orthopedics","emergency","decision-rule"],"hx":true,"yr":2,"pearls":["Sensitivity near 100% for fracture","Reduces unnecessary radiographs","Applies to adults and children over 5"],"source_ref":"https://www.ncbi.nlm.nih.gov/books/NBK559166/"}
];
